 p_id=>wwv_flow_imp.id(281758232007098410)
,p_name=>'header'
,p_region_name=>'header'
,p_template=>4501440665235496320
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with comment_stats as (',
'    select cm.ticket_id,',
'           count(*) as update_count,',
'           max(cm.created_ts) as last_update_ts',
'      from app_ticket_comment cm',
'     group by cm.ticket_id',
')',
'select t.ticket_number,',
'       null as card_html,',
'       t.status_code,',
'       t.priority_code,',
'       p.priority_name,',
'       c.category_name,',
'       case c.category_name',
'           when ''Bug'' then ''Bug''',
'           when ''Question'' then ''Question''',
'           when ''Enhancement'' then ''Enhancement''',
'           when ''Data Issue'' then ''DataIssue''',
'       end as category_class,',
'       case c.category_name',
'           when ''Bug'' then ''fa-bug''',
'           when ''Question'' then ''fa-question-circle''',
'           when ''Enhancement'' then ''fa-lightbulb-o''',
'           when ''Data Issue'' then ''fa-database''',
'       end as category_icon,',
'       t.submitted_by,',
'       nvl(t.assigned_to, ''Unassigned'') as assigned_to,',
'       to_char(t.created_ts, ''DD-MON-YYYY HH24:MI'') as created_date,',
'       t.description,',
'       t.sr_number,',
'       t.jira_ref,',
'',
'       nvl(cs.update_count, 0) as update_count,',
'',
'       case',
'           when cs.last_update_ts is null then ''No updates''',
'           else to_char(cs.last_update_ts, ''DD-MON-YYYY HH24:MI'')',
'       end as last_update_date,',
'',
'       case',
'           when cs.last_update_ts is null then ''No updates''',
'           when trunc(sysdate - cast(cs.last_update_ts as date)) = 0 then ''Today''',
'           when trunc(sysdate - cast(cs.last_update_ts as date)) = 1 then ''1 day ago''',
'           else trunc(sysdate - cast(cs.last_update_ts as date)) || '' days ago''',
'       end as last_update_ago,',
'',
'       ''Unassigned'' as queue_name,',
'',
'       case',
'           when trunc(sysdate - cast(t.created_ts as date)) = 0 then ''Today''',
'           when trunc(sysdate - cast(t.created_ts as date)) = 1 then ''1 day''',
'           else trunc(sysdate - cast(t.created_ts as date)) || '' days''',
'       end as ticket_age',
'',
'  from app_ticket t',
'  join app_ticket_priority p',
'    on p.priority_code = t.priority_code',
'  join app_ticket_category c',
'    on c.category_code = t.category_code',
'  left join comment_stats cs',
'    on cs.ticket_id = t.ticket_id',
' where t.ticket_id = :P6001_TICKET_ID'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
