wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(281734647448938167)
,p_name=>'Updates'
,p_region_name=>'comments_report'
,p_parent_plug_id=>wwv_flow_imp.id(394086923839838649)
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:t-Region--hideHeader js-addHiddenHeadingRoleDesc:t-Region--accent1:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Comments--chat:t-Comments--iconsRounded'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT c.comment_id,',
'NULL AS attribute_1,',
'NULL AS attribute_2,',
'NULL AS attribute_3,',
'NULL AS attribute_4,',
'',
'       UPPER(',
'           SUBSTR(c.created_by, 1, 1)',
'           || SUBSTR(c.created_by, INSTR(c.created_by, ''.'') + 1, 1)',
'       ) AS user_icon,',
'       c.comment_text',
'         || CASE WHEN c.file_name IS NOT NULL THEN',
'                CHR(10) || CHR(10)',
'                || ''<a href="f?p=&APP_ID.:5005:'' || :APP_SESSION',
'                || '':::NO:P5005_ATTACHMENT_ID:'' || c.comment_id',
'                || ''" target="_blank">''',
'                || ''<span class="fa fa-paperclip"></span> ''',
'                || c.file_name || ''</a>''',
'            END AS comment_text,',
'       c.created_by AS user_name,',
'       TO_CHAR(c.created_ts, ''DD-MON-YYYY HH24:MI'') AS comment_date,',
'       CASE WHEN c.is_internal = ''Y''',
'     THEN ''<span class="tkt-tag tkt-tag-internal"><i class="fa fa-lock" style="color: #0d9488;"></i> Internal</span>''',
'     ELSE ''<span class="tkt-tag tkt-tag-public"><i class="fa fa-globe" style="color: green;"></i> Public</span>''',
'END AS actions,',
'       CASE WHEN c.is_internal = ''Y'' THEN ''comment-internal'' ELSE ''comment-public'' END AS comment_modifiers',
'  FROM app_ticket_comment c',
' WHERE c.ticket_id = :P6001_TICKET_ID',
'   AND (c.is_internal = ''N''',
'        OR EXISTS (SELECT 1 FROM app_user_roles',
'                    WHERE UPPER(username) = UPPER(:APP_USER)',
'                      AND role_code IN (''ADMIN'',''SUPPORT_DEV'')',
'                      AND is_active = ''Y''))',
' ORDER BY c.created_ts DESC',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P6001_TICKET_ID'
,p_lazy_loading=>false
,p_query_row_template=>2613168815517880001
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No comments yet.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
