,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    pkg_app_ticket.update_priority(',
'        p_ticket_id    => :P6001_TICKET_ID,',
'        p_new_priority => :P6001_NEW_PRIORITY,',
'        p_username     => :APP_USER',
'    );',
'',
'    if :P6001_REASON is not null then',
'        pkg_app_ticket.add_comment(',
'            p_ticket_id    => :P6001_TICKET_ID,',
'            p_comment_text => to_clob(:P6001_REASON),',
'            p_is_internal  => ''Y'',',
'            p_username     => :APP_USER',
'        );',
'    end if;',
'',
'    select p.priority_name',
'      into :P6001_CURRENT_PRIORITY',
'      from app_ticket_priority p',
'     where p.priority_code = :P6001_NEW_PRIORITY;',
'',
'    :P6001_PRIORITY_CODE := :P6001_NEW_PRIORITY;',
'    :P6001_PRIORITY_NAME := :P6001_CURRENT_PRIORITY;',
'end;',
''))
