,p_process_name=>'fetch'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT t.ticket_number,',
'       t.status_code,',
'       t.priority_code,',
'       p.priority_name,',
'       c.category_name,',
'       CASE c.category_name',
'           WHEN ''Bug'' THEN ''Bug''',
'           WHEN ''Question'' THEN ''Question''',
'           WHEN ''Enhancement'' THEN ''Enhancement''',
'           WHEN ''Data Issue'' THEN ''DataIssue''',
'       END,',
'       CASE c.category_name',
'           WHEN ''Bug'' THEN ''fa-bug''',
'           WHEN ''Question'' THEN ''fa-question-circle''',
'           WHEN ''Enhancement'' THEN ''fa-lightbulb-o''',
'           WHEN ''Data Issue'' THEN ''fa-database''',
'       END,',
'       t.submitted_by,',
'       NVL(t.assigned_to, ''Unassigned''),',
'       TO_CHAR(t.created_ts, ''DD-MON-YYYY HH24:MI''),',
'       t.description,',
'       t.subject',
'  INTO :P6001_TICKET_NUMBER,',
'       :P6001_STATUS_CODE,',
'       :P6001_PRIORITY_CODE,',
'       :P6001_PRIORITY_NAME,',
'       :P6001_CATEGORY_NAME,',
'       :P6001_CATEGORY_CLASS,',
'       :P6001_CATEGORY_ICON,',
'       :P6001_SUBMITTED_BY,',
'       :P6001_ASSIGNED_TO,',
'       :P6001_CREATED_DATE,',
'       :P6001_DESCRIPTION,',
'       :P6001_SUBJECT',
'  FROM app_ticket t',
'  JOIN app_ticket_priority p ON p.priority_code = t.priority_code',
'  JOIN app_ticket_category c ON c.category_code = t.category_code',
' WHERE t.ticket_id = :P6001_TICKET_ID;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>114502352389734213
);
end;
