'DECLARE',
'    l_result VARCHAR2(4000);',
'BEGIN',
'    l_result := pkg_bpm_tasks.action_task(',
'        p_task_number   => TO_NUMBER(apex_application.g_x01),',
'        p_action        => apex_application.g_x02,',
'        p_comment       => apex_application.g_x03,',
'        p_assignee_id   => apex_application.g_x04,',
'        p_assignee_type => NVL(apex_application.g_x05, ''user'')',
