prompt --application/pages/page_06004
begin
wwv_flow_imp_page.create_page(
 p_id=>6004
,p_name=>'Task List Faceted'
,p_alias=>'TASK-LIST-FACETED'
,p_step_title=>'Task List Faceted'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#APP_FILES#bpm_task_detail_js#MIN#.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function refreshTasks() {',
'',
'    var spinner = apex.util.showSpinner($("#bpm_tasks_ir"));',
'',
'    apex.server.process("REFRESH_TASKS", {}, {',
'',
'        dataType: "json",',
'',
'        success: function (data) {',
'',
'            try {',
'',
'                if (data.status === "OK") {',
'                    apex.region("bpm_tasks_ir").refresh();',
'                } else {',
'                    apex.message.alert(data.message);',
'                }',
'',
'            } finally {',
'',
'                spinner.remove();',
'',
'            }',
'',
'        },',
'',
'        error: function (jqXHR, textStatus, errorThrown) {',
'',
'            spinner.remove();',
'',
'            console.error("Refresh failed:", textStatus, errorThrown);',
'            apex.message.alert("Refresh failed.");',
'',
'        }',
'',
'    });',
'',
'}'))
,p_css_file_urls=>'#APP_FILES#bpm_task_detail_css#MIN#.css'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#t_Body_title {',
'    background-color: #252321;',
