'}',
'',
'/* Card grid layout */',
'.kb-card-grid .t-Report-report,',
'.kb-card-grid .t-Report-report tbody { display: flex; flex-wrap: wrap; gap: 16px; }',
'.kb-card-grid .t-Report-report thead { display: none; }',
'.kb-card-grid .t-Report-report tr { display: contents; }',
'.kb-card-grid .t-Report-report td { display: block; padding: 0; border: none; }',
'',
'/* Individual card */',
'.kb-card {',
