,p_display_sequence=>10
,p_region_css_classes=>'kb-card-grid'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT task_number,',
'       NULL AS card_html,',
'       title,',
'       task_type,',
'       category,',
'       NVL(assignee_id, ''(Unassigned)'') AS assignee_id,',
'       priority,',
'       days_pending,',
'       comment_count,',
unistr('       NVL(from_user_display, ''\2014'') AS from_user_display,'),
'       tracking_status,',
'       s.status_label,',
'       CASE priority',
'           WHEN 1 THEN ''P1'' WHEN 2 THEN ''P2'' ELSE ''P3''',
'       END AS priority_label,',
'       CASE',
'           WHEN days_pending >= 90 THEN ''kb-age--critical''',
'           WHEN days_pending >= 30 THEN ''kb-age--warn''',
'           ELSE ''kb-age--normal''',
'       END AS age_class,',
'       CASE tracking_status',
'           WHEN ''NEW'' THEN ''kb-status--new''',
'           WHEN ''IN_PROGRESS'' THEN ''kb-status--in_progress''',
'           WHEN ''WAITING'' THEN ''kb-status--waiting''',
'           WHEN ''DONE'' THEN ''kb-status--done''',
'           ELSE ''kb-status--new''',
'       END AS status_css,',
'       CASE tracking_status',
'           WHEN ''NEW'' THEN ''kb-border--new''',
'           WHEN ''IN_PROGRESS'' THEN ''kb-border--in_progress''',
'           WHEN ''WAITING'' THEN ''kb-border--waiting''',
'           WHEN ''DONE'' THEN ''kb-border--done''',
'           ELSE ''kb-border--new''',
'       END AS border_css',
'  FROM bpm_task_board_v v',
'  JOIN bpm_task_statuses s ON s.status_code = v.tracking_status',
' WHERE (v.tracking_status = :P6006_STATUS_FILTER OR :P6006_STATUS_FILTER IS NULL)',
'   AND (v.category = :P6006_CATEGORY_FILTER OR :P6006_CATEGORY_FILTER IS NULL)',
' ORDER BY v.priority, v.assigned_ts'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P6006_STATUS_FILTER,P6006_CATEGORY_FILTER'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
