wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1047853180084364229)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE_TASK_STATUS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_task_number NUMBER := TO_NUMBER(apex_application.g_x01);',
'    l_new_status  VARCHAR2(30) := apex_application.g_x02;',
'BEGIN',
'    UPDATE bpm_workflow_tasks',
'       SET tracking_status = l_new_status',
'     WHERE task_number = l_task_number;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''ERROR'');',
'        apex_json.write(''message'', ''Task '' || l_task_number || '' not found.'');',
'        apex_json.close_object;',
'        RETURN;',
'    END IF;',
'',
'    COMMIT;',
'',
'    apex_json.open_object;',
'    apex_json.write(''status'', ''OK'');',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''ERROR'');',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>880600100100000060
);
end;
