,p_page_component_map=>'27'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(300593407080493615)
,p_plug_name=>'User Role List'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3371237801798025892
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ROWNUM AS "ID",',
'       role_code,',
'       source',
'  FROM (',
'        -- Priority 1: REST (APEX collection exists = REST succeeded at login)',
'        SELECT c001 AS role_code,',
'               ''REST (Real-Time)'' AS source',
'          FROM apex_collections',
'         WHERE collection_name = ''FUSION_USER_ROLES''',
'        UNION ALL',
'        -- Priority 2: BIP (only if collection does NOT exist = REST failed)',
'        SELECT r.role_common_name AS role_code,',
'               ''BIP (Daily Snapshot)'' AS source',
'          FROM fa_user_accounts a',
'          JOIN fa_user_roles    r ON r.user_guid = a.user_guid',
'         WHERE UPPER(a.username) = UPPER(:APP_USER)',
'           AND (r.effective_end_date IS NULL',
'                OR r.effective_end_date > SYSTIMESTAMP)',
'           AND NOT EXISTS (',
'                SELECT 1',
'                  FROM apex_collections',
'                 WHERE collection_name = ''FUSION_USER_ROLES''',
'               )',
'        ORDER BY role_code',
'       )',
''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>25
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>true
