'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."COL_POSITION" IS ''Ordinal position (1-based) in the SELECT list'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."FUSION_SOURCE" IS ''Expression from the Fusion (first) SELECT branch'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."LAWSON_SOURCE" IS ''Expression from the Lawson (second) SELECT branch'';',
