'create or replace package col_profiler as',
'',
'  -- Profile a single table',
'  procedure profile_table (',
'    p_table_name   in varchar2,',
'    p_all_thresh   in number   default 6,   -- show ALL values when distinct <= this',
'    p_sample_n     in number   default 6    -- otherwise show this many samples',
'  );',
'',
'  -- Profile multiple tables in one call',
'  procedure profile_tables (',
'    p_table_names  in sys.odcivarchar2list,  -- e.g. sys.odcivarchar2list(''T1'',''T2'')',
'    p_all_thresh   in number   default 6,',
'    p_sample_n     in number   default 6',
'  );',
'',
'  -- Convenience: wipe all profile data (or for one table)',
'  procedure clear_profile (',
'    p_table_name   in varchar2 default null',
'  );',
'',
'  -- Auto-parse Fusion/Lawson mashup views into VIEW_COLUMN_CROSSWALK',
'  --   p_view_name    => exact view name (null = use pattern)',
'  --   p_name_pattern => LIKE pattern to discover views (default ''%_V'')',
'  --   p_owner        => schema owner (default current user)',
'  procedure refresh_view_crosswalk (',
'    p_view_name    in varchar2 default null,',
'    p_name_pattern in varchar2 default ''%_V'',',
'    p_owner        in varchar2 default user',
'  );',
'',
'end col_profiler;',
