'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BICC_FILES_V" ("FILE_NAME", "FILE_SIZE", "FILE_SIZE_KB", "LAST_MODIFIED", "BATCH_ID", "FILE_TIMESTAMP", "LOAD_TYPE", "LOADER_AVAILABLE") AS ',
'  WITH o AS (',
'  SELECT',
'    regexp_substr(object_name, ''[^/]+$'') AS file_name,',
'    bytes                               AS file_size,',
'    last_modified',
'  FROM table(',
'    dbms_cloud.list_objects(',
'      credential_name => ''OBJ_STORE_CRED_JK'',',
'      location_uri    => ''https://objectstorage.us-ashburn-1.oraclecloud.com/n/idlhcuqzdx2c/b/SCI_Conversion/o/''',
'    )',
'  )',
'  WHERE lower(object_name) LIKE ''%.zip''',
'),',
'x AS (',
'  SELECT',
'    file_name,',
'    file_size,',
'    round(file_size / 1024, 2) AS file_size_kb,',
'    last_modified,',
'    regexp_substr(file_name, ''batch(\d+)'', 1, 1, ''i'', 1) AS batch_id,',
'    to_timestamp(',
'      regexp_substr(file_name, ''-(\d{8}_\d{6})\.zip'', 1, 1, ''i'', 1),',
'      ''YYYYMMDD_HH24MISS''',
'    ) AS file_timestamp',
'  FROM o',
')',
'SELECT',
'  x.file_name,',
'  x.file_size,',
'  x.file_size_kb,',
'  x.last_modified,',
'  x.batch_id,',
'  x.file_timestamp,',
'  coalesce(m.load_type, ''UNMAPPED'') AS load_type,',
'  CASE',
'    WHEN m.load_type IS NOT NULL THEN ''Y''',
'    ELSE ''N''',
'  END AS loader_available',
'FROM x',
'OUTER APPLY (',
'  SELECT m1.load_type',
'  FROM bicc_loader_map m1',
'  WHERE m1.is_active = ''Y''',
'    AND m1.load_type IS NOT NULL',
'    AND m1.file_like IS NOT NULL',
'    AND lower(x.file_name) LIKE lower(m1.file_like)',
'  ORDER BY m1.priority NULLS LAST',
'  FETCH FIRST 1 ROW ONLY',
') m;',
'',
'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FBX_AP_INVOICE_HDR_V" ("SOURCESYSTEM", "SOURCEPRECEDENCE", "INVOICEID", "INVOICENUMBER", "INVOICECURRENCY", "PAYMENTCURRENCY", "INVOICEAMOUNT", "INVOICEDATE", "ACCOUNTINGDATE", "BUSINESSUNIT", "SUPPLIER", "'
||'SUPPLIERNUMBER", "SUPPLIERSITE", "VALIDATIONSTATUS", "APPROVALSTATUS", "PAIDSTATUS", "ACCOUNTINGSTATUS", "INVOICETYPE", "PAYMENTTERMS", "INVOICESOURCE", "DESCRIPTION", "PURCHASEORDERNUMBER", "CREATEDBY", "CREATIONDATE", "LASTUPDATEDATE") AS ',
'  select',
'  ''Fusion'' as SourceSystem,',
'  1       as SourcePrecedence, -- use later if we need to pick a winner',
'',
'  to_char(f.invoiceid) as InvoiceId,',
'  f.invoiceheaderinvoicenum as InvoiceNumber,',
'',
'  f.invoiceheaderinvoicecurrencycode as InvoiceCurrency,',
'  f.invoiceheaderpaymentcurrencycode as PaymentCurrency,',
'',
'  f.invoiceheaderinvoiceamount as InvoiceAmount,',
'  f.invoiceheaderinvoicedate  as InvoiceDate,',
'  f.invoiceheadergldate       as AccountingDate,',
'',
'  /* If we can add BU / SupplierNumber to Fusion extract, update here, for now hardcode BU to Greenville County Schools */',
'  ''Greenville County Schools'' as BusinessUnit,',
'  f.partypartyname            as Supplier,',
'  cast(null as varchar2(30))  as SupplierNumber,',
'  f.partysitepartysitename    as SupplierSite,',
'',
'  f.invoicehdrvalidationstatuscode as ValidationStatus,',
'  f.invoiceheaderapprovalstatus    as ApprovalStatus,',
'  f.invoiceheaderpaymentstatusflag as PaidStatus,',
'  f.invoicehdraccountingstatuscode as AccountingStatus,',
'',
'  f.invoiceheaderinvoicetypelookupcode as InvoiceType,',
'',
'  /* If you extract true terms (name/code), map it here */',
'  cast(null as varchar2(60)) as PaymentTerms,',
'',
'  /* If you extract InvoiceSource, map it here */',
'  cast(null as varchar2(120)) as InvoiceSource,',
'',
'  f.invoiceheaderdescription as Description,',
'  f.purchaseordersegment1    as PurchaseOrderNumber,',
'',
'  f.invoiceheadercreatedby     as CreatedBy,',
'  f.invoiceheadercreationdate  as CreationDate,',
'  f.invoiceheaderlastupdatedate as LastUpdateDate',
'',
'from fbx_ap_invoice_hdr f',
'',
'union all',
'',
'/* =========================',
'   LAWSON (transaction table + vendor master)',
'   ========================= */',
'select',
'  ''Lawson'' as SourceSystem,',
'  2       as SourcePrecedence,',
'',
'  /* Lawson doesn''t have a Fusion InvoiceId; use OBJ_ID if present, else composite */',
'  coalesce(',
'    to_char(a.obj_id),',
'    to_char(a.company) || '':'' || trim(a.vendor) || '':'' || trim(a.invoice) || '':'' || to_char(a.suffix)',
'  ) as InvoiceId,',
'',
'  /* Include suffix when present */',
'  case',
'    when nvl(a.suffix,0) = 0 then trim(a.invoice)',
'    else trim(a.invoice) || ''-'' || to_char(a.suffix)',
'  end as InvoiceNumber,',
'',
'  trim(a.inv_currency) as InvoiceCurrency,',
'  trim(a.pay_currency) as PaymentCurrency,',
'',
'  a.tran_inv_amt                    as InvoiceAmount,',
'  cast(a.invoice_dte  as date)      as InvoiceDate,',
'  cast(a.distrib_date as date)      as AccountingDate,',
'',
'  /* Pick what audience recognizes (PROC_LEVEL or COMPANY) */',
'  trim(a.proc_level)                as BusinessUnit,',
'',
'  /* Vendor name from APVENMAST; fallback to vendor code if missing */',
'  nvl(trim(v.vendor_vname), trim(a.vendor)) as Supplier,',
'  trim(a.vendor)                     as SupplierNumber,',
'',
'  /* "site" surrogate in Lawson */',
'  trim(a.remit_to_code)              as SupplierSite,',
'',
'  /* Legacy assumed closed/actionless unless we map actual codes */',
'  ''Validated''                        as ValidationStatus,',
'',
'  case when trim(a.approved_flag) = ''Y'' then ''Approved'' else ''Required'' end as ApprovalStatus,',
'',
'  case',
'    when a.cancel_date is not null then ''Canceled''',
'    when nvl(a.tran_paid_amt,0) = 0 then ''Unpaid''',
'    when nvl(a.tran_paid_amt,0) >= nvl(a.tran_inv_amt,0) then ''Paid''',
'    else ''Partially Paid''',
'  end as PaidStatus,',
'',
'  ''Accounted''                        as AccountingStatus,',
'',
'  trim(a.invoice_type)               as InvoiceType,',
'  trim(a.terms_cd)                   as PaymentTerms,',
'  trim(a.invoice_source)             as InvoiceSource,',
'  trim(a.description)                as Description,',
'  trim(a.po_number)                  as PurchaseOrderNumber,',
'',
'  trim(a.created_by)                 as CreatedBy,',
'  cast(a.create_date as timestamp)   as CreationDate,',
'  cast(a.last_updt_date as timestamp) as LastUpdateDate',
'',
'from ls_apps_apinvoice a',
'left join ls_apps_apvenmast v',
'  on trim(v.vendor) = trim(a.vendor);',
'',
'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FBX_PO_HDR_V" ("SOURCESYSTEM", "SOURCEPRECEDENCE", "POID", "PONUMBER", "PORELEASE", "POREVISION", "POTYPE", "DOCUMENTSTATUS", "APPROVEDSTATUS", "BUSINESSUNIT", "BUYERCODE", "SUPPLIER", "SUPPLIERNUMBER", "SU'
||'PPLIERSITE", "CURRENCYCODE", "POAMOUNT", "OPENPOAMOUNT", "NBR_LINES", "CLOSED_LINES", "FREIGHTTERMS", "PAYMENTTERMS", "LOCATION", "VENDORORDERNUM", "PODATE", "CREATIONDATE", "LASTUPDATEDATE", "CLOSEDATE", "LAST_EXTRACT_RUN_ID", "LAST_EXTRACT_RUN_TS")'
||' AS ',
'  select',
'  ''Fusion'' as sourcesystem,',
'  1       as sourceprecedence,',
'',
'  to_char(f.poheaderid)        as poid,',
'  trim(f.po_number)           as ponumber,',
'  cast(null as number)        as porelease,',
'  f.revisionnum               as porevision,',
'  f.po_type                   as potype,',
'  f.documentstatus            as documentstatus,',
'  case when f.approvedflag is not null then f.approvedflag end as approvedstatus,',
'',
'  /* If you later add BU to the Fusion extract, swap this */',
'  ''Greenville County Schools'' as businessunit,',
'  cast(null as varchar2(30))  as buyercode,',
'',
'  /* You only have vendorid today; name can be joined later from a Fusion suppliers table */',
'  cast(null as varchar2(240)) as supplier,',
'  to_char(f.vendorid)         as suppliernumber,',
'  to_char(f.vendorsiteid)     as suppliersite,',
'',
'  f.currencycode              as currencycode,',
'',
unistr('  /* pick a reasonable \201Cheader amount\201D */'),
'  coalesce(f.blankettotalamount, f.amountlimit, f.amountreleased) as poamount,',
'  cast(null as number)        as openpoamount,',
'',
'  cast(null as number)        as nbr_lines,',
'  cast(null as number)        as closed_lines,',
'',
'  cast(null as varchar2(30))  as freightterms,',
'  cast(null as varchar2(60))  as paymentterms,',
'',
'  cast(null as varchar2(30))  as location,',
'  f.vendor_order_num          as vendorordernum,',
'',
unistr('  /* \201CPO date\201D isn\2019t always explicit; use startdate when present else creation */'),
'  coalesce(f.startdate_ts, f.creationdate_ts) as podate,',
'  f.creationdate_ts          as creationdate,',
'  f.lastupdatedate_ts        as lastupdatedate,',
'  f.closeddate_ts            as closedate,',
'',
'  f.last_extract_run_id,',
'  f.last_extract_run_ts',
'',
'from fbx_po_hdr f',
'',
'',
'union all',
'',
'',
'/* =========================',
'   LAWSON (LS_APPS_PURCHORDER + optional vendor name)',
'   ========================= */',
'select',
'  ''Lawson'' as sourcesystem,',
'  2       as sourceprecedence,',
'',
'  /* Lawson doesn''t have Fusion POHEADERID; use PO_OBJ_ID if populated, else composite */',
'  coalesce(',
'    nullif(trim(l.po_obj_id), ''''),',
'    to_char(l.company) || '':'' || trim(l.po_number) || '':'' || to_char(l.po_release)',
'  ) as poid,',
'',
'  trim(l.po_number)            as ponumber,',
'  l.po_release                 as porelease,',
'  l.po_revision                as porevision,',
'  trim(l.po_code)              as potype,',
'',
'  /* derive a simple status */',
'  case',
'    when trim(l.cancelled_fl) = ''Y'' then ''CANCELLED''',
'    when trim(l.closed_fl)    = ''Y'' then ''CLOSED''',
'    else ''OPEN''',
'  end as documentstatus,',
'',
'  case when nvl(l.po_approved,0) = 1 then ''Y'' else ''N'' end as approvedstatus,',
'',
'  /* Audience-friendly BU */',
'  trim(l.process_level)        as businessunit,',
'  trim(l.buyer_code)           as buyercode,',
'',
'  /* vendor name from APVENMAST if available; fallback to vendor code */',
'  nvl(trim(v.vendor_vname), trim(l.vendor)) as supplier,',
'  trim(l.vendor)               as suppliernumber,',
'  cast(null as varchar2(60))   as suppliersite,',
'',
'  trim(l.currency_code)        as currencycode,',
'  l.tot_order_amt              as poamount,',
'  l.open_po_amt                as openpoamount,',
'',
'  l.nbr_lines                  as nbr_lines,',
'  l.closed_lines               as closed_lines,',
'',
'  trim(l.freight_terms)        as freightterms,',
'  trim(l.term_code)            as paymentterms,',
'',
'  trim(l.location)             as location,',
'  cast(null as varchar2(240))  as vendorordernum,',
'',
'  l.po_date                    as podate,',
'  l.po_date                    as creationdate,     -- best available proxy in Lawson',
'  l.last_updt_date             as lastupdatedate,',
'  l.close_date                 as closedate,',
'',
'  cast(null as varchar2(64))   as last_extract_run_id,',
'  cast(null as timestamp(6))   as last_extract_run_ts',
'',
'from ls_apps_purchorder l',
'left join ls_apps_apvenmast v',
'  on trim(v.vendor) = trim(l.vendor);',
'',
'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FBX_PO_LINES_V" ("SOURCESYSTEM", "SOURCEPRECEDENCE", "POID", "PONUMBER", "PORELEASE", "SUPPLIER", "SUPPLIERNUMBER", "POHEADERID", "POLINEID", "LINENUM", "CREATEDBY", "CREATIONDATE", "FUNDSSTATUS", "ITEMDESC'
||'RIPTION", "LASTUPDATEDBY", "LINESTATUS", "LISTPRICE", "MATCHINGBASIS", "PURCHASEBASIS", "SHIPPINGUOMCODE", "UNITPRICE", "UOMCODE", "QUANTITY", "EXTENDED_AMT") AS ',
'  select',
'  ''Fusion'' as sourcesystem,',
'  1       as sourceprecedence,',
'',
'  to_char(h.poheaderid)              as poid,',
'  trim(h.po_number)                  as ponumber,',
'  cast(null as number)               as porelease,',
'',
'  cast(null as varchar2(240))        as supplier,        -- populate later if/when you add Fusion supplier name',
'  to_char(h.vendorid)                as suppliernumber,',
'',
'  l.poheaderid                       as poheaderid,',
'  to_char(l.polineid)                as polineid,',
'  l.linenum                          as linenum,',
'',
'  l.createdby                        as createdby,',
'  l.creationdate                     as creationdate,',
'  l.fundsstatus                      as fundsstatus,',
'  l.itemdescription                  as itemdescription,',
'  l.lastupdatedby                    as lastupdatedby,',
'  l.linestatus                       as linestatus,',
'  l.listprice                        as listprice,',
'  l.matchingbasis                    as matchingbasis,',
'  l.purchasebasis                    as purchasebasis,',
'  l.shippinguomcode                  as shippinguomcode,',
'  l.unitprice                        as unitprice,',
'  l.uomcode                          as uomcode,',
'',
'  cast(null as number(13,4))         as quantity,',
'  cast(null as number(18,2))         as extended_amt',
'from fbx_po_lines l',
'join fbx_po_hdr h',
'  on h.poheaderid = l.poheaderid',
'',
'union all',
'',
'/* =========================',
'   LAWSON (LS_APPS_POLINE + LS_APPS_PURCHORDER + APVENMAST)',
'   ========================= */',
'select',
'  ''Lawson'' as sourcesystem,',
'  2       as sourceprecedence,',
'',
'  /* Match the exact POID logic used in FBX_PO_HDR_V (PO_OBJ_ID else composite) */',
'  coalesce(',
'    nullif(trim(ph.po_obj_id), ''''),',
'    to_char(pl.company) || '':'' || trim(pl.po_number) || '':'' || to_char(pl.po_release)',
'  )                                     as poid,',
'',
'  trim(pl.po_number)                    as ponumber,',
'  pl.po_release                         as porelease,',
'',
'  nvl(trim(v.vendor_vname), trim(pl.vendor)) as supplier,',
'  trim(pl.vendor)                       as suppliernumber,',
'',
'  cast(null as number(18,0))            as poheaderid,',
'',
'  /* Lawson has no POLINEID; make a stable surrogate */',
'  to_char(pl.company) || '':'' || trim(pl.po_number) || '':'' || to_char(pl.po_release) || '':'' || to_char(pl.line_nbr)',
'                                        as polineid,',
'',
'  pl.line_nbr                           as linenum,',
'',
'  trim(pl.created_by)                   as createdby,',
'  pl.last_updt_date                     as creationdate,  -- best available timestamp in this table',
'  cast(null as varchar2(30))            as fundsstatus,',
'',
'  /* closest equivalent to Fusion ITEMDESCRIPTION */',
'  cast(trim(pl.description) as varchar2(4000)) as itemdescription,',
'',
'  trim(pl.last_update_by)               as lastupdatedby,',
'',
'  /* closest equivalent to Fusion LINESTATUS */',
'  case',
'    when trim(pl.closed_fl) = ''Y'' then ''CLOSED''',
'    else ''OPEN''',
'  end                                   as linestatus,',
'',
'  /* closest equivalents to Fusion pricing columns */',
'  pl.vbuy_unit_cst                      as listprice,',
'  trim(pl.match_class)                  as matchingbasis,',
'  trim(pl.cost_option)                  as purchasebasis,',
'  trim(pl.ent_buy_uom)                  as shippinguomcode,',
'  pl.ent_unit_cst                       as unitprice,',
'  trim(pl.ent_buy_uom)                  as uomcode,',
'',
'  pl.quantity                           as quantity,',
'  pl.extended_amt                       as extended_amt',
'from ls_apps_poline pl',
'left join ls_apps_purchorder ph',
'  on ph.company    = pl.company',
' and trim(ph.po_number) = trim(pl.po_number)',
' and ph.po_release = pl.po_release',
'left join ls_apps_apvenmast v',
'  on trim(v.vendor) = trim(pl.vendor);',
'',
'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "FBX_SUPPLIER_HDR_V" ("SOURCE_SYSTEM", "VENDORID", "PARTYID", "SEGMENT1", "ALTERNATENAMEPARTYNAME", "ALTERNATENAMEPARTYNAMEID", "ALIASPARTYNAME", "ALIASPARTYNAMEID", "VENDORTYPELOOKUPCODE", "ORGANIZATIONTYPE'
||'LOOKUPCODE", "BUSINESSRELATIONSHIP", "BCNOTAPPLICABLEFLAG", "FEDERALREPORTABLEFLAG", "INCOMETAXID", "INCOMETAXIDFLAG", "TYPE1099", "CREATEDBY", "CREATIONDATE", "CREATIONSOURCE", "LASTUPDATEDBY", "LASTUPDATEDATE", "LASTUPDATELOGIN", "OBJECTVERSIONNUMB'
||'ER") AS ',
'  SELECT',
'    ''FUSION'' AS source_system,',
'',
'    f.vendorid,',
'    f.partyid,',
'    f.segment1,',
'',
'    f.alternatenamepartyname,',
'    f.alternatenamepartynameid,',
'    f.aliaspartyname,',
'    f.aliaspartynameid,',
'',
'    f.vendortypelookupcode,',
'    f.organizationtypelookupcode,',
'    f.businessrelationship,',
'    f.bcnotapplicableflag,',
'    f.federalreportableflag,',
'    f.incometaxid,',
'    f.incometaxidflag,',
'    f.type1099,',
'',
'    f.createdby,',
'    f.creationdate,',
'    f.creationsource,',
'    f.lastupdatedby,',
'    f.lastupdatedate,',
'    f.lastupdatelogin,',
'    f.objectversionnumber',
'FROM fbx_fusion_supplier_hdr f',
'',
'UNION ALL',
'',
'SELECT',
'    ''LAWSON'' AS source_system,',
'',
unistr('    /* Use AP_OBJ_ID as the \201Cvendorid/partyid\201D equivalent for Lawson.'),
unistr('       It\2019s not the same concept as Fusion VendorId, but it\2019s a stable numeric id. */'),
'    CAST(l.ap_obj_id AS NUMBER(18)) AS vendorid,',
'    CAST(l.ap_obj_id AS NUMBER(18)) AS partyid,',
'',
'    TRIM(l.vendor) AS segment1,',
'',
unistr('    /* Best \201Csupplier name\201D mapping */'),
'    NVL(NULLIF(TRIM(l.legal_name), ''''), TRIM(l.vendor_vname)) AS alternatenamepartyname,',
'    NULL AS alternatenamepartynameid,',
'',
unistr('    /* Best \201Calias/short name\201D mapping */'),
'    NVL(NULLIF(TRIM(l.vendor_sname), ''''), TRIM(l.vendor_vname)) AS aliaspartyname,',
'    NULL AS aliaspartynameid,',
'',
'    /* Constants / light derivations */',
'    ''SUPPLIER'' AS vendortypelookupcode,',
'    ''CORPORATION'' AS organizationtypelookupcode, ',
'    ''SPEND_AUTHORIZED'' AS businessrelationship, ',
'    NULL AS bcnotapplicableflag,',
'',
'    NULL AS federalreportableflag,               -- no obvious Lawson equivalent in DDL',
'    TRIM(l.tax_id) AS incometaxid,',
'    CASE WHEN NULLIF(TRIM(l.tax_id), '''') IS NOT NULL THEN ''Y'' ELSE ''N'' END AS incometaxidflag,',
'    NULL AS type1099,',
'',
'    /* Audit mapping */',
'    COALESCE(NULLIF(TRIM(l.created_by), ''''), NULLIF(TRIM(l.operator), '''')) AS createdby,',
'    l.create_date AS creationdate,',
'    ''LAWSON'' AS creationsource,',
'    NULLIF(TRIM(l.last_update_by), '''') AS lastupdatedby,',
'    l.last_updt_date AS lastupdatedate,',
'    NULL AS lastupdatelogin,',
'    NULL AS objectversionnumber',
'        FROM ls_apps_apvenmast l;',
'',
'  CREATE OR REPLACE FORCE EDITIONABLE VIEW "WKSP_FREEDEMO_LS_APPS_TABLES_V" ("OWNER", "TABLE_NAME", "EST_ROWS", "STATS_LAST_ANALYZED", "LAST_DML_SEEN", "INS_SINCE_STATS", "UPD_SINCE_STATS", "DEL_SINCE_STATS") AS ',
'  select',
'  t.owner,',
'  t.table_name,',
'  t.num_rows                           as est_rows,',
'  t.last_analyzed                      as stats_last_analyzed,',
'  m.timestamp                          as last_dml_seen,',
'  nvl(m.inserts, 0)                    as ins_since_stats,',
'  nvl(m.updates, 0)                    as upd_since_stats,',
'  nvl(m.deletes, 0)                    as del_since_stats',
'from all_tables t',
'left join all_tab_modifications m',
'  on m.table_owner = t.owner',
' and m.table_name  = t.table_name',
'where t.owner = ''WKSP_FREEDEMO''',
'  and (t.table_name like ''LS_APPS\_%'' escape ''\'' OR t.table_name like ''LMGHRDB\_%'' escape ''\'')',
'  and nvl(t.num_rows, 0) > 0',
'order by nvl(m.timestamp, t.last_analyzed) desc nulls last,',
'         t.num_rows desc nulls last,',
'         t.table_name;',
'',
'   COMMENT ON COLUMN "FBX_AP_INVOICE_HDR_V"."INVOICEID" IS ''Unique invoice identifier - Fusion uses native ID, Lawson builds composite key'';',
'',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."VIEW_NAME" IS ''Name of the mashup view'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."COLUMN_NAME" IS ''Unified column alias in the view'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."COL_POSITION" IS ''Ordinal position (1-based) in the SELECT list'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."FUSION_SOURCE" IS ''Expression from the Fusion (first) SELECT branch'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."LAWSON_SOURCE" IS ''Expression from the Lawson (second) SELECT branch'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."FUSION_TABLE" IS ''Source table(s) for the Fusion branch'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."LAWSON_TABLE" IS ''Source table(s) for the Lawson branch'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."NOTES" IS ''Manual annotations (preserved across refreshes when auto_parsed=N)'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."AUTO_PARSED" IS ''Y = auto-populated by parser, N = hand-edited (protected from overwrite)'';',
'   COMMENT ON COLUMN "VIEW_COLUMN_CROSSWALK"."LAST_REFRESHED" IS ''Timestamp of last auto-refresh'';',
'   COMMENT ON TABLE "VIEW_COLUMN_CROSSWALK"  IS ''Auto-parsed Fusion vs Lawson column-level crosswalk for mashup views'';',
'create or replace package body col_profiler as',
'',
'  --------------------------------------------------------------------',
'  procedure profile_table (',
'    p_table_name   in varchar2,',
'    p_all_thresh   in number   default 6,',
'    p_sample_n     in number   default 6',
'  ) is',
'    l_tname    varchar2(128) := upper(trim(p_table_name));',
'    l_total    number;',
'    l_nonblank number;',
'    l_distinct number;',
'    l_null_pct number;',
'    l_sql      clob;',
'    l_vals_sql clob;',
'    l_vals     varchar2(4000);',
'  begin',
'    -- Validate table exists in current schema',
'    declare',
'      l_dummy number;',
'    begin',
'      select 1 into l_dummy',
'      from   user_tables',
'      where  table_name = l_tname',
'      and    rownum = 1;',
'    exception',
'      when no_data_found then',
'        raise_application_error(-20001, ''Table not found: '' || l_tname);',
'    end;',
'',
'    execute immediate ''select count(*) from "'' || l_tname || ''"'' into l_total;',
'',
'    -- Remove previous profile for this table',
'    delete from column_profile where table_name = l_tname;',
'',
'    for c in (',
'      select column_name, data_type',
'      from   user_tab_columns',
'      where  table_name = l_tname',
'        and  data_type not in (''CLOB'',''BLOB'',''LONG'',''LONG RAW'', ''RAW'')',
'      order  by column_id',
'    ) loop',
'      l_vals := null;',
'',
'      if c.data_type in (''CHAR'',''VARCHAR2'',''NCHAR'',''NVARCHAR2'') then',
'        ---------------------------------------------------------',
'        -- String columns: trim blanks before counting',
'        ---------------------------------------------------------',
'        l_sql :=',
'          ''select ''||',
'          ''  sum(case when nullif(trim("''||c.column_name||''"),'''''''') is not null then 1 else 0 end),''||',
'          ''  count(distinct nullif(trim("''||c.column_name||''"),'''''''')) ''||',
'          '''))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(219910759296195542)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'from "''||l_tname||''"'';',
'        execute immediate l_sql into l_nonblank, l_distinct;',
'',
'        if nvl(l_nonblank,0) = 0 then continue; end if;',
'',
'        if l_distinct <= p_all_thresh then',
'          l_vals_sql :=',
'            ''select listagg(val,'''', '''') within group (order by val) ''||',
'            ''from (select distinct trim("''||c.column_name||''") as val ''||',
'            ''      from "''||l_tname||''"''||',
'            ''      where nullif(trim("''||c.column_name||''"),'''''''') is not null)'';',
'        else',
'          l_vals_sql :=',
'            ''select listagg(val,'''', '''') within group (order by val) ''||',
'            ''from (select val from (''||',
'            ''        select distinct trim("''||c.column_name||''") as val ''||',
'            ''        from "''||l_tname||''"''||',
'            ''        where nullif(trim("''||c.column_name||''"),'''''''') is not null''||',
'            ''      ) order by val fetch first ''||p_sample_n||'' rows only)'';',
'        end if;',
'        execute immediate l_vals_sql into l_vals;',
'',
'      else',
'        ---------------------------------------------------------',
'        -- NUMBER / DATE / TIMESTAMP columns',
'        ---------------------------------------------------------',
'        l_sql :=',
'          ''select count("''||c.column_name||''"), count(distinct "''||c.column_name||''") ''||',
'          ''from "''||l_tname||''"'';',
'        execute immediate l_sql into l_nonblank, l_distinct;',
'',
'        if nvl(l_nonblank,0) = 0 then continue; end if;',
'',
'        if l_distinct <= p_all_thresh then',
'          l_vals_sql :=',
'            ''select listagg(val,'''', '''') within group (order by val) ''||',
'            ''from (select distinct to_char("''||c.column_name||''") as val ''||',
'            ''      from "''||l_tname||''"''||',
'            ''      where "''||c.column_name||''" is not null)'';',
'        else',
'          l_vals_sql :=',
'            ''select listagg(val,'''', '''') within group (order by val) ''||',
'            ''from (select val from (''||',
'            ''        select distinct to_char("''||c.column_name||''") as val ''||',
'            ''        from "''||l_tname||''"''||',
'            ''        where "''||c.column_name||''" is not null''||',
'            ''      ) order by val fetch first ''||p_sample_n||'' rows only)'';',
'        end if;',
'        execute immediate l_vals_sql into l_vals;',
'      end if;',
'',
'      l_null_pct := case',
'                      when l_total > 0',
'                      then round((l_total - nvl(l_nonblank,0)) / l_total * 100, 2)',
'                      else 0',
'                    end;',
'',
'      insert into column_profile',
'        (table_name, column_name, total_rows, nonblank_count,',
'         distinct_count, null_pct, sample_values)',
'      values',
'        (l_tname, c.column_name, l_total, l_nonblank,',
'         l_distinct, l_null_pct, l_vals);',
'',
'    end loop;',
'',
'    commit;',
'  end profile_table;',
'',
'  --------------------------------------------------------------------',
'  procedure profile_tables (',
'    p_table_names  in sys.odcivarchar2list,',
'    p_all_thresh   in number   default 6,',
'    p_sample_n     in number   default 6',
'  ) is',
'  begin',
'    for i in 1 .. p_table_names.count loop',
'      profile_table(',
'        p_table_name => p_table_names(i),',
'        p_all_thresh => p_all_thresh,',
'        p_sample_n   => p_sample_n',
'      );',
'    end loop;',
'  end profile_tables;',
'',
'  --------------------------------------------------------------------',
'  procedure clear_profile (',
'    p_table_name in varchar2 default null',
'  ) is',
'  begin',
'    if p_table_name is null then',
'      delete from column_profile;',
'    else',
'      delete from column_profile',
'      where  table_name = upper(trim(p_table_name));',
'    end if;',
'    commit;',
'  end clear_profile;',
'',
'  --------------------------------------------------------------------',
'  -- refresh_view_crosswalk',
'  --   Parses views built as  SELECT <Fusion> UNION ALL SELECT <Lawson>',
'  --   and populates VIEW_COLUMN_CROSSWALK with column-level mappings.',
'  --------------------------------------------------------------------',
'  procedure refresh_view_crosswalk (',
'    p_view_name    in varchar2 default null,',
'    p_name_pattern in varchar2 default ''%_V'',',
'    p_owner        in varchar2 default user',
'  ) is',
'    v_text         clob;',
'    v_union_pos    number;',
'    v_fusion       clob;',
'    v_lawson       clob;',
'    v_sel_end      number;',
'    v_from_pos     number;',
'    v_list         clob;',
'    v_fusion_tbl   varchar2(400);',
'    v_lawson_tbl   varchar2(400);',
'',
'    type t_arr is table of varchar2(4000) index by pls_integer;',
'    v_f  t_arr;',
'    v_l  t_arr;',
'    v_fc pls_integer;',
'    v_lc pls_integer;',
'    v_cnt pls_integer;',
'',
'    v_alias  varchar2(128);',
'    v_fexpr  varchar2(4000);',
'    v_lexpr  varchar2(4000);',
'',
'    ----------------------------------------------------------------',
'    -- split a SELECT-list on top-level commas (paren-aware only)',
'    ----------------------------------------------------------------',
'    procedure split_csv(p_txt clob, p_out out t_arr, p_cnt out pls_integer) is',
'      v_depth pls_integer := 0;',
'      v_start pls_integer := 1;',
'      v_n     pls_integer := 0;',
'      v_ch    char(1);',
'    begin',
'      for i in 1 .. nvl(length(p_txt), 0) loop',
'        v_ch := substr(p_txt, i, 1);',
'        if    v_ch = ''('' then v_depth := v_depth + 1;',
'        elsif v_ch = '')'' then v_depth := v_depth - 1;',
'        elsif v_ch = '','' and v_depth = 0 then',
'          v_n := v_n + 1;',
'          p_out(v_n) := substr(trim(substr(p_txt, v_start, i - v_start)), 1, 4000);',
'          v_start := i + 1;',
'        end if;',
'      end loop;',
'      v_n := v_n + 1;',
'      p_out(v_n) := substr(trim(substr(p_txt, v_start)), 1, 4000);',
'      p_cnt := v_n;',
'    end split_csv;',
'',
'    ----------------------------------------------------------------',
'    -- strip trailing alias:  "expr AS alias" -> "expr"',
'    ----------------------------------------------------------------',
'    function strip_alias(p_item varchar2) return varchar2 is',
'      v_pos number;',
'    begin',
'      v_pos := regexp_instr(p_item, ''\s[Aa][Ss]\s+\S+\s*$'');',
'      if v_pos > 0 then return trim(substr(p_item, 1, v_pos - 1)); end if;',
'      return trim(p_item);',
'    end strip_alias;',
'',
'    ----------------------------------------------------------------',
'    -- extract FROM-clause table names up to WHERE/GROUP/ORDER',
'    ----------------------------------------------------------------',
'    function get_tables(p_half clob) return varchar2 is',
'      v_from  number;',
'      v_chunk varchar2(4000);',
'      v_end   number;',
'    begin',
'      v_from := regexp_instr(p_half, ''\sFROM\s'', 1, 1, 0, ''i'');',
'      if v_from = 0 then return null; end if;',
'      v_chunk := substr(trim(substr(p_half, v_from + 5, 1000)), 1, 4000);',
'      v_end   := regexp_instr(upper(v_chunk), ''\s(WHERE|GROUP|ORDER|HAVING)\s'');',
'      if v_end > 0 then v_chunk := substr(v_chunk, 1, v_end - 1); end if;',
'      return substr(regexp_replace(trim(v_chunk), ''\s+'', '' ''), 1, 400);',
'    end get_tables;',
'',
'  begin',
'    for rec in (',
'      select view_name, text',
'        from all_views',
'       where owner = upper(p_owner)',
'         and (  (p_view_name is not null and view_name = upper(p_view_name))',
'             or (p_view_name is null     and view_name like upper(p_name_pattern)))',
'       order by view_name',
'    ) loop',
'      -- strip comments (one-liners)',
'      v_text := regexp_replace(rec.text, ''--.*$'', '''', 1, 0, ''m'');',
'      v_text := regexp_replace(v_text, ''/\*.*?\*/'', '' '', 1, 0, ''n'');',
'',
'      -- find UNION ALL',
'      v_union_pos := regexp_instr(v_text, ''\sUNION\s+ALL\s'', 1, 1, 0, ''i'');',
'      if v_union_pos = 0 then',
'        dbms_output.put_line(''SKIP '' || rec.view_name || '': no UNION ALL'');',
'        continue;',
'      end if;',
'',
'      v_fusion := substr(v_text, 1, v_union_pos);',
'      v_lawson := regexp_replace(substr(v_text, v_union_pos), ''^\s*UNION\s+ALL\s*'', '''', 1, 1, ''i'');',
'',
'      -- Fusion branch: SELECT list between SELECT and FROM',
'      v_sel_end  := instr(upper(v_fusion), ''SELECT'') + 6;',
'      v_from_pos := regexp_instr(v_fusion, ''\sFROM\s'', 1, 1, 0, ''i'');',
'      v_list     := substr(v_fusion, v_sel_end, v_from_pos - v_sel_end);',
'      split_csv(v_list, v_f, v_fc);',
'      v_fusion_tbl := get_tables(v_fusion);',
'',
'      -- Lawson branch: same',
'      v_sel_end  := instr(upper(v_lawson), ''SELECT'') + 6;',
'      v_from_pos := regexp_instr(v_lawson, ''\sFROM\s'', 1, 1, 0, ''i'');',
'      v_list     := substr(v_lawson, v_sel_end, v_from_pos - v_sel_end);',
'      split_csv(v_list, v_l, v_lc);',
'      v_lawson_tbl := get_tables(v_lawson);',
'',
'      v_cnt := greatest(nvl(v_fc, 0), nvl(v_lc, 0));',
'',
'      for i in 1 .. v_cnt loop',
'        -- column name from data dictionary',
'        begin',
'          select column_name into v_alias',
'            from all_tab_columns',
'           where owner = upper(p_owner)',
'             and table_name = rec.view_name',
'             and column_id = i;',
'        exception when no_data_found then',
'          v_alias := ''COL_'' || i;',
'        end;',
'',
'        if v_f.exists(i) then v_fexpr := substr(strip_alias(v_f(i)), 1, 4000);',
'        else v_fexpr := null; end if;',
'',
'        if v_l.exists(i) then v_lexpr := substr(strip_alias(v_l(i)), 1, 4000);',
'        else v_lexpr := null; end if;',
'',
'        merge into view_column_crosswalk tgt',
'        using (',
'          select upper(rec.view_name) as vn, v_alias as cn, i as cp,',
'                 v_fexpr as fe, v_lexpr as le,',
'                 v_fusion_tbl as ft, v_lawson_tbl as lt',
'            from dual',
'        ) src',
'        on (tgt.view_name = src.vn and tgt.column_name = src.cn)',
'        when matched then',
'          update set',
'            tgt.col_position   = src.cp,',
'            tgt.fusion_source  = case when tgt.auto_parsed = ''Y'' then src.fe else tgt.fusion_source end,',
'            tgt.lawson_source  = case when tgt.auto_parsed = ''Y'' then src.le else tgt.lawson_source end,',
'            tgt.fusion_table   = src.ft,',
'            tgt.lawson_table   = src.lt,',
'            tgt.last_refreshed = systimestamp',
'          where tgt.auto_parsed = ''Y''',
'        when not matched then',
'          insert (view_name, column_name, col_position, fusion_source, lawson_source,',
'                  fusion_table, lawson_table, auto_parsed, last_refreshed)',
'          values (src.vn, src.cn, src.cp, src.fe, src.le,',
'                  src.ft, src.lt, ''Y'', systimestamp);',
'      end loop;',
'',
'      delete from view_column_crosswalk',
'       where view_name = upper(rec.view_name)',
'         and col_position > v_cnt;',
'',
'      dbms_output.put_line(''OK '' || rec.view_name || '' ('' || v_cnt || '' cols)'');',
'      v_f.delete;',
'      v_l.delete;',
'    end loop;',
'',
'    commit;',
'  end refresh_view_crosswalk;',
'',
'end col_profiler;',
'/',
'create or replace package body pkg_benchmark as',
'    type t_timing is record (',
'        label varchar2(100),',
'        start_ts timestamp,',
'        end_ts timestamp,',
'        elapsed_seconds number',
'    );',
'    ',
'    type t_timing_table is table of t_timing;',
'    g_timings t_timing_table := t_timing_table();',
'    ',
'    procedure start_timer(p_label in varchar2) is',
'        l_timing t_timing;',
'    begin',
'        l_timing.label := p_label;',
'        l_timing.start_ts := systimestamp;',
'        g_timings.extend;',
'        g_timings(g_timings.last) := l_timing;',
'    end start_timer;',
'    ',
'    procedure stop_timer(p_label in varchar2) is',
'    begin',
'        for i in reverse 1..g_timings.count loop',
'            if g_timings(i).label = p_label and g_timings(i).end_ts is null then',
'                g_timings(i).end_ts := systimestamp;',
'                g_timings(i).elapsed_seconds := ',
'                    extract(day from (g_timings(i).end_ts - g_timings(i).start_ts)) * 86400 +',
'                    extract(hour from (g_timings(i).end_ts - g_timings(i).start_ts)) * 3600 +',
'                    extract(minute from (g_timings(i).end_ts - g_timings(i).start_ts)) * 60 +',
'                    extract(second from (g_timings(i).end_ts - g_timings(i).start_ts));',
'                exit;',
'            end if;',
'        end loop;',
'    end stop_timer;',
'    ',
'    procedure print_results is',
'    begin',
'        dbms_output.put_line(rpad(''Label'', 50) || rpad(''Elapsed (sec)'', 15) || ''Start Time'');',
'        dbms_output.put_line(rpad(''-'', 50, ''-'') || rpad(''-'', 15, ''-'') || rpad(''-'', 30, ''-''));',
'        ',
'        for i in 1..g_timings.count loop',
'            dbms_output.put_line(',
'                rpad(g_timings(i).label, 50) || ',
'                rpad(to_char(g_timings(i).elapsed_seconds, ''999,990.99''), 15) ||',
'                to_char(g_timings(i).start_ts, ''YYYY-MM-DD HH24:MI:SS'')',
'            );',
'        end loop;',
'    end print_results;',
'    ',
'    procedure clear_results is',
'    begin',
'        g_timings := t_timing_table();',
'    end clear_results;',
'end pkg_benchmark;',
'/',
'create or replace package body pkg_bicc_ap_invoice_hdr as',
'',
'    -- =========================================================================',
'    -- LOAD (private)',
'    -- =========================================================================',
unistr('    -- Flow: extract_and_stage_csv \2192 COPY_DATA \2192 INSERT...SELECT'),
'    -- =========================================================================',
'',
'    procedure load(',
'        p_file_name  in varchar2,',
'        p_job_id     in number',
'    ) is',
'        l_error_msg     varchar2(4000);',
'        l_rows_inserted number := 0;',
'        l_run_id        varchar2(64) := sys_guid();',
'        l_staging_uri   varchar2(500);',
'    begin',
'        delete from stg_fbx_ap_invoice_hdr where job_id = p_job_id;',
'',
'        -- Step 1: Extract CSV from ZIP, upload to Object Storage',
'        pkg_bicc_common.extract_and_stage_csv(',
'            p_file_name    => p_file_name,',
'            p_staging_name => ''staging/ap_invoice_hdr_current.csv''',
'        );',
'',
'        -- Step 2: Load CSV into landing table via COPY_DATA',
'        execute immediate ''TRUNCATE TABLE landing_ap_invoice_hdr'';',
'',
'        l_staging_uri := pkg_bicc_common.gc_bucket_uri || ''staging/ap_invoice_hdr_current.csv'';',
'',
'        dbms_cloud.copy_data(',
'            table_name      => ''LANDING_AP_INVOICE_HDR'',',
'            credential_name => pkg_bicc_common.gc_credential,',
'            file_uri_list   => l_staging_uri,',
'            format          => json_object(',
'                                 ''type'' value ''csv'',',
'                                 ''skipheaders'' value ''1''',
'                               )',
'        );',
'',
'        -- Step 3: Cherry-pick columns from landing into staging',
'        insert into stg_fbx_ap_invoice_hdr (',
'            job_id,',
'            invoiceid,',
'            invoiceheaderinvoicenum,',
'            invoiceheadervouchernum,',
'            partypartyname,',
'            partysitepartysitename,',
'            invoiceheaderinvoicedate,',
'            invoiceheadergldate,',
'            invoiceheadercreationdate,',
'            invoiceheaderinvoiceamount,',
'            invoiceheaderinvoicecurrencycode,',
'            invoiceheaderpaymentcurrencycode,',
'            invoiceheaderamountpaid,',
'            invoicehdrvalidationstatuscode,',
'            invoiceheaderapprovalstatus,',
'            invoiceheaderpaymentstatusflag,',
'            invoicehdraccountingstatuscode,',
'            invoiceheaderinvoicetypelookupcode,',
'            invoiceheaderpaygrouplookupcode,',
'            invoiceheadertermsdate,',
'            invoiceheaderdescription,',
'            purchaseordersegment1,',
'            invoiceheadercreatedby,',
'            invoiceheaderlastupdatedate,',
'            last_extract_run_id,',
'            last_extract_run_ts',
'        )',
'        select',
'            p_job_id,',
'            pkg_bicc_common.safe_to_number(l.INVOICEID),',
'            l.INVOICEHEADERINVOICENUM,',
'            nullif(trim(l.INVOICEHEADERVOUCHERNUM), ''''),',
'            l.PARTYPARTYNAME,',
'            l.PARTYSITEPARTYSITENAME,',
'            cast(pkg_bicc_common.safe_to_timestamp(l.INVOICEHEADERINVOICEDATE) as date),',
'            cast(pkg_bicc_common.safe_to_timestamp(l.INVOICEHEADERGLDATE) as date),',
'            pkg_bicc_common.safe_to_timestamp(l.INVOICEHEADERCREATIONDATE),',
'            pkg_bicc_common.safe_to_number(l.INVOICEHEADERINVOICEAMOUNT),',
'            l.INVOICEHEADERINVOICECURRENCYCODE,',
'            l.INVOICEHEADERPAYMENTCURRENCYCODE,',
'            pkg_bicc_common.safe_to_number(l.INVOICEHEADERAMOUNTPAID),',
'            l.INVOICEHDRVALIDATIONSTATUSCODE,',
'            l.INVOICEHEADERAPPROVALSTATUS,',
'            l.INVOICEHEADERPAYMENTSTATUSFLAG,',
'            l.INVOICEHDRACCOUNTINGSTATUSCODE,',
'            l.INVOICEHEADERINVOICETYPELOOKUPCODE,',
'            nullif(trim(l.INVOICEHEADERPAYGROUPLOOKUPCODE), ''''),',
'            cast(pkg_bicc_common.safe_to_timestamp(l.INVOICEHEADERTERMSDATE) as date),',
'            nullif(trim(l.INVOICEHEADERDESCRIPTION), ''''),',
'            nullif(trim(l.PURCHASEORDERSEGMENT1), ''''),',
'            l.INVOICEHEADERCREATEDBY,',
'            pkg_bicc_common.safe_to_timestamp(l.INVOICEHEADERLASTUPDATEDATE),',
'            l_run_id,',
'            systimestamp',
'        from landing_ap_invoice_hdr l;',
'',
'        l_rows_inserted := sql%rowcount;',
'        commit;',
'',
'        insert into bicc_load_log (',
'            load_type, file_name, step, rows_processed, rows_inserted, status',
'        ) values (',
'            ''AP_INVOICE_HDR'', p_file_name, ''LOAD_STG'', l_rows_inserted, l_rows_inserted, ''SUCCESS''',
'        );',
'        commit;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            rollback;',
'            insert into bicc_load_log (',
'                load_type, file_name, step, status, error_message',
'            ) values (',
'                ''AP_INVOICE_HDR'', p_file_name, ''LOAD_STG'', ''ERROR'', l_error_msg',
'            );',
'            commit;',
'            raise;',
'    end load;',
'',
'',
'    -- =========================================================================',
'    -- PREVIEW (private)',
'    -- =========================================================================',
'',
'    procedure preview(',
'        p_job_id          in  number,',
'        p_new_count       out number,',
'        p_changed_count   out number,',
'        p_unchanged_count out number',
'    ) is',
'        l_matched number;',
'    begin',
'        select count(*) into p_new_count',
'        from (',
'            select distinct invoiceid',
'            from stg_fbx_ap_invoice_hdr',
'            where job_id = p_job_id',
'        ) s',
'        where not exists (',
'            select 1 from fbx_ap_invoice_hdr f where f.invoiceid = s.invoiceid',
'        );',
'',
'        select count(*) into l_matched',
'        from (',
'            select distinct invoiceid',
'            from stg_fbx_ap_invoice_hdr',
'            where job_id = p_job_id',
'        ) s',
'        where exists (',
'            select 1 from fbx_ap_invoice_hdr f where f.invoiceid = s.invoiceid',
'        );',
'',
'        select count(*) into p_unchanged_count',
'        from (',
'            select',
'                invoiceid,',
'                invoiceheaderinvoicenum,',
'                invoiceheadervouchernum,',
'                partypartyname,',
'                partysitepartysitename,',
'                invoiceheaderinvoicedate,',
'                invoiceheadergldate,',
'                invoiceheaderinvoiceamount,',
'                invoiceheaderinvoicecurrencycode,',
'                invoiceheaderpaymentcurrencycode,',
'                invoiceheaderamountpaid,',
'                invoicehdrvalidationstatuscode,',
'                invoiceheaderapprovalstatus,',
'                invoiceheaderpaymentstatusflag,',
'                invoicehdraccountingstatuscode,',
'                invoiceheaderinvoicetypelookupcode,',
'                invoiceheaderpaygrouplookupcode,',
'                invoiceheadertermsdate,',
'                invoiceheaderdescription,',
'                purchaseordersegment1,',
'                invoiceheadercreatedby',
'            from (',
'                select',
'                    s.*,',
'                    row_number() over (partition by invoiceid order by rowid) rn',
'                from stg_fbx_ap_invoice_hdr s',
'                where job_id = p_job_id',
'            )',
'            where rn = 1',
'            intersect',
'            select',
'                invoiceid,',
'                invoiceheaderinvoicenum,',
'                invoiceheadervouchernum,',
'                partypartyname,',
'                partysitepartysitename,',
'                invoiceheaderinvoicedate,',
'                invoiceheadergldate,',
'                invoiceheaderinvoiceamount,',
'                invoiceheaderinvoicecurrencycode,',
'                invoiceheaderpaymentcurrencycode,',
'                invoiceheaderamountpaid,',
'                invoicehdrvalidationstatuscode,',
'                invoiceheaderapprovalstatus,',
'                invoiceheaderpaymentstatusflag,',
'                invoicehdraccountingstatuscode,',
'                invoiceheaderinvoicetypelookupcode,',
'                invoiceheaderpaygrouplookupcode,',
'                invoiceheadertermsdate,',
'                invoiceheaderdescription,',
'                purchaseordersegment1,',
'                invoiceheadercreatedby',
'            from fbx_ap_invoice_hdr',
'        );',
'',
'        p_changed_count := l_matched - p_unchanged_count;',
'    end preview;',
'',
'',
'    -- =========================================================================',
'    -- LOAD AND PREVIEW (public)',
'    -- =========================================================================',
'',
'    function load_and_preview(p_file_name in varchar2) return number is',
'        l_job_id      number;',
'        l_rows_loaded number;',
'        l_new         number;',
'        l_changed     number;',
'        l_unchanged   number;',
'        l_error_msg   varchar2(4000);',
'    begin',
'        insert into bicc_load_job (',
'            load_type, file_name, status, loaded_by, loaded_ts',
'        ) values (',
'            ''AP_INVOICE_HDR'', p_file_name, ''LOADING'', coalesce(v(''APP_USER''), user), systimestamp',
'        )',
'        returning job_id into l_job_id;',
'',
'        load(p_file_name => p_file_name, p_job_id => l_job_id);',
'',
'        select count(distinct invoiceid) into l_rows_loaded',
'        from stg_fbx_ap_invoice_hdr',
'        where job_id = l_job_id;',
'',
'        preview(',
'            p_job_id          => l_job_id,',
'            p_new_count       => l_new,',
'            p_changed_count   => l_changed,',
'            p_unchanged_count => l_unchanged',
'        );',
'',
'        update bicc_load_job',
'        set rows_loaded     = l_rows_loaded,',
'            new_count       = l_new,',
'            changed_count   = l_changed,',
'            unchanged_count = l_unchanged,',
'            status          = ''STAGED''',
'        where job_id = l_job_id;',
'',
'        commit;',
'        return l_job_id;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            update bicc_load_job',
'            set status        = ''ERROR'',',
'                error_message = l_error_msg',
'            where job_id = l_job_id;',
'            commit;',
'            raise;',
'    end load_and_preview;',
'',
'',
'    -- =========================================================================',
'    -- MERGE (public)',
'    -- =========================================================================',
'',
'    procedure merge(p_job_id in number) is',
'        l_rowcount  number := 0;',
'        l_error_msg varchar2(4000);',
'    begin',
'        merge into fbx_ap_invoice_hdr f',
'        using (',
'            select * from (',
'                select',
'                    s.*,',
'                    row_number() over (',
'                        partition by invoiceid',
'                        order by rowid',
'                    ) rn',
'                from stg_fbx_ap_invoice_hdr s',
'                where job_id = p_job_id',
'            )',
'            where rn = 1',
'        ) s',
'        on (f.invoiceid = s.invoiceid)',
'        when matched then update set',
'            f.invoiceheaderinvoicenum          = s.invoiceheaderinvoicenum,',
'            f.invoiceheadervouchernum          = s.invoiceheadervouchernum,',
'            f.partypartyname                   = s.partypartyname,',
'            f.partysitepartysitename           = s.partysitepartysitename,',
'            f.invoiceheaderinvoicedate         = s.invoiceheaderinvoicedate,',
'            f.invoiceheadergldate              = s.invoiceheadergldate,',
'            f.invoiceheadercreationdate        = s.invoiceheadercreationdate,',
'            f.invoiceheaderinvoiceamount       = s.invoiceheaderinvoiceamount,',
'            f.invoiceheaderinvoicecurrencycode = s.invoiceheaderinvoicecurrencycode,',
'            f.invoiceheaderpaymentcurrencycode = s.invoiceheaderpaymentcurrencycode,',
'            f.invoiceheaderamountpaid          = s.invoiceheaderamountpaid,',
'            f.invoicehdrvalidationstatuscode   = s.invoicehdrvalidationstatuscode,',
'            f.invoiceheaderapprovalstatus      = s.invoiceheaderapprovalstatus,',
'            f.invoiceheaderpaymentstatusflag   = s.invoiceheaderpaymentstatusflag,',
'            f.invoicehdraccountingstatuscode   = s.invoicehdraccountingstatuscode,',
'            f.invoiceheaderinvoicetypelookupcode = s.invoiceheaderinvoicetypelookupcode,',
'            f.invoiceheaderpaygrouplookupcode  = s.invoiceheaderpaygrouplookupcode,',
'            f.invoiceheadertermsdate           = s.invoiceheadertermsdate,',
'            f.invoiceheaderdescription         = s.invoiceheaderdescription,',
'            f.purchaseordersegment1            = s.purchaseordersegment1,',
'            f.invoiceheadercreatedby           = s.invoiceheadercreatedby,',
'            f.invoiceheaderlastupdatedate      = s.invoiceheaderlastupdatedate,',
'            f.last_extract_run_id              = s.last_extract_run_id,',
'            f.last_extract_run_ts              = s.last_extract_run_ts',
'        when not matched then insert (',
'            invoiceid,',
'            invoiceheaderinvoicenum,',
'            invoiceheadervouchernum,',
'            partypartyname,',
'            partysitepartysitename,',
'            invoiceheaderinvoicedate,',
'            invoiceheadergldate,',
'            invoiceheadercreationdate,',
'            invoiceheaderinvoiceamount,',
'            invoiceheaderinvoicecurrencycode,',
'            invoiceheaderpaymentcurrencycode,',
'            invoiceheaderamountpaid,',
'            invoicehdrvalidationstatuscode,',
'            invoiceheaderapprovalstatus,',
'            invoiceheaderpaymentstatusflag,',
'            invoicehdraccountingstatuscode,',
'            invoiceheaderinvoicetypelookupcode,',
'            invoiceheaderpaygrouplookupcode,',
'            invoiceheadertermsdate,',
'            invoiceheaderdescription,',
'            purchaseordersegment1,',
'            invoiceheadercreatedby,',
'            invoiceheaderlastupdatedate,',
'            last_extract_run_id,',
'            last_extract_run_ts',
'        ) values (',
'            s.invoiceid,',
'            s.invoiceheaderinvoicenum,',
'            s.invoiceheadervouchernum,',
'            s.partypartyname,',
'            s.partysitepartysitename,',
'            s.invoiceheaderinvoicedate,',
'            s.invoiceheadergldate,',
'            s.invoiceheadercreationdate,',
'            s.invoiceheaderinvoiceamount,',
'            s.invoiceheaderinvoicecurrencycode,',
'            s.invoiceheaderpaymentcurrencycode,',
'            s.invoiceheaderamountpaid,',
'            s.invoicehdrvalidationstatuscode,',
'            s.invoiceheaderapprovalstatus,',
'            s.invoiceheaderpaymentstatusflag,',
'            s.invoicehdraccountingstatuscode,',
'            s.invoiceheaderinvoicetypelookupcode,',
'            s.invoiceheaderpaygrouplookupcode,',
'            s.invoiceheadertermsdate,',
'            s.invoiceheaderdescription,',
'            s.purchaseordersegment1,',
'            s.invoiceheadercreatedby,',
'            s.invoiceheaderlastupdatedate,',
'            s.last_extract_run_id,',
'            s.last_extract_run_ts',
'        );',
'',
'        l_rowcount := sql%rowcount;',
'',
'        delete from stg_fbx_ap_invoice_hdr where job_id = p_job_id;',
'',
'        update bicc_load_job',
'        set status    = ''MERGED'',',
'            merged_by = coalesce(v(''APP_USER''), user),',
'            merged_ts = systimestamp',
'        where job_id = p_job_id;',
'',
'        insert into bicc_load_log (',
'            load_type, step, rows_updated, status',
'        ) values (',
'            ''AP_INVOICE_HDR'', ''MERGE_FBX'', l_rowcount, ''SUCCESS''',
'        );',
'',
'        commit;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            rollback;',
'            insert into bicc_load_log (',
'                load_type, step, status, error_message',
'            ) values (',
'                ''AP_INVOICE_HDR'', ''MERGE_FBX'', ''ERROR'', l_error_msg',
'            );',
'            commit;',
'            raise;',
'    end merge;',
'',
'end pkg_bicc_ap_invoice_hdr;',
'/',
'create or replace package body pkg_bicc_common as',
'',
'    -- =========================================================================',
'    -- SAFE TYPE CONVERSIONS',
'    -- =========================================================================',
'',
'    function safe_to_number(p_str varchar2) return number is',
'    begin',
'        if p_str is null or trim(p_str) is null then',
'            return null;',
'        end if;',
'        return to_number(trim(p_str));',
'    exception',
'        when others then',
'            return null;',
'    end safe_to_number;',
'',
'    function safe_to_timestamp(p_str varchar2) return timestamp is',
'        v varchar2(200) := trim(p_str);',
'    begin',
'        if v is null then',
'            return null;',
'        end if;',
'',
'        -- 6/14/2025',
'        if regexp_like(v, ''^\d{1,2}/\d{1,2}/\d{4}$'') then',
'            return to_timestamp(v, ''MM/DD/YYYY'');',
'        end if;',
'',
'        -- 2025-06-14',
'        if regexp_like(v, ''^\d{4}-\d{2}-\d{2}$'') then',
'            return to_timestamp(v, ''YYYY-MM-DD'');',
'        end if;',
'',
'        -- 2025-06-14 12:30:44.123',
'        if regexp_like(v, ''^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}(\.\d+)?$'') then',
'            return to_timestamp(v, ''YYYY-MM-DD HH24:MI:SS.FF'');',
'        end if;',
'',
'        -- 2025-06-14T12:30:44.123Z (or without Z)',
'        if instr(v, ''T'') > 0 then',
'            v := replace(v, ''T'', '' '');',
'            v := rtrim(v, ''Z'');',
'            if regexp_like(v, ''^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}(\.\d+)?$'') then',
'                return to_timestamp(v, ''YYYY-MM-DD HH24:MI:SS.FF'');',
'            end if;',
'        end if;',
'',
'        return null;',
'    exception',
'        when others then',
'            return null;',
'    end safe_to_timestamp;',
'',
'    -- =========================================================================',
'    -- EXTRACT CSV FROM ZIP AND UPLOAD TO OBJECT STORAGE',
'    -- =========================================================================',
'    -- Reusable across all entities. Each entity passes a different',
'    -- p_staging_name (e.g., ''staging/hcm_employee_current.csv'').',
'    -- =========================================================================',
'',
'    procedure extract_and_stage_csv(',
'     '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(219910759296195542)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'   p_file_name    in varchar2,',
'        p_credential   in varchar2 default gc_credential,',
'        p_bucket_uri   in varchar2 default gc_bucket_uri,',
'        p_staging_name in varchar2',
'    ) is',
'        l_zip_blob  blob;',
'        l_csv_blob  blob;',
'        l_file_list apex_zip.t_files;',
'        l_csv_name  varchar2(32767);',
'    begin',
'        -- Download ZIP from Object Storage',
'        l_zip_blob := dbms_cloud.get_object(',
'            credential_name => p_credential,',
'            object_uri      => p_bucket_uri || p_file_name',
'        );',
'',
'        -- Find first CSV in the ZIP',
'        l_file_list := apex_zip.get_files(p_zipped_blob => l_zip_blob);',
'        for i in 1 .. l_file_list.count loop',
'            if lower(l_file_list(i)) like ''%.csv'' then',
'                l_csv_name := l_file_list(i);',
'                exit;',
'            end if;',
'        end loop;',
'        if l_csv_name is null then',
'            l_csv_name := l_file_list(1);',
'        end if;',
'',
'        -- Extract CSV content',
'        l_csv_blob := apex_zip.get_file_content(',
'            p_zipped_blob => l_zip_blob,',
'            p_file_name   => l_csv_name',
'        );',
'',
'        -- Upload CSV to staging location so COPY_DATA can read it',
'        dbms_cloud.put_object(',
'            credential_name => p_credential,',
'            object_uri      => p_bucket_uri || p_staging_name,',
'            contents        => l_csv_blob',
'        );',
'    end extract_and_stage_csv;',
'',
'',
'    -- =========================================================================',
'    -- REFRESH FILE LIST',
'    -- =========================================================================',
'    -- Syncs bicc_files table with files currently in Object Storage',
'    -- =========================================================================',
'',
'    procedure refresh_bicc_files is',
'   begin',
'  merge into bicc_files t',
'  using (',
'    select',
'      file_name,',
'      file_size,',
'      file_size_kb,',
'      last_modified,',
'      load_type,',
'      loader_available,',
'      file_timestamp',
'    from bicc_files_v',
'  ) s',
'  on (t.file_name = s.file_name)',
'',
'  when matched then update set',
'      t.file_size        = s.file_size,',
'      t.file_size_kb     = s.file_size_kb,',
'      t.last_modified    = s.last_modified,',
'      t.load_type        = s.load_type,',
'      t.loader_available = s.loader_available,',
'      t.file_timestamp   = s.file_timestamp,',
'      t.refreshed_ts     = systimestamp',
'',
'  when not matched then insert (',
'      file_name,',
'      file_size,',
'      file_size_kb,',
'      last_modified,',
'      load_type,',
'      loader_available,',
'      file_timestamp,',
'      refreshed_ts',
'  ) values (',
'      s.file_name,',
'      s.file_size,',
'      s.file_size_kb,',
'      s.last_modified,',
'      s.load_type,',
'      s.loader_available,',
'      s.file_timestamp,',
'      systimestamp',
'  );',
'',
'end refresh_bicc_files;',
'',
'',
'    -- =========================================================================',
'    -- PURGE OLD FILES FROM OBJECT STORAGE',
'    -- =========================================================================',
'    -- Deletes ZIP files older than p_retention_days from Object Storage',
'    -- =========================================================================',
'',
'    procedure purge_bicc_objectstore(',
'        p_retention_days in number default 60',
'    ) is',
'        l_cutoff   timestamp := systimestamp - numtodsinterval(p_retention_days, ''DAY'');',
'        l_ts_text  varchar2(32);',
'        l_file_ts  timestamp;',
'    begin',
'        for r in (',
'            select object_name',
'            from table(dbms_cloud.list_objects(',
'                credential_name => gc_credential,',
'                location_uri    => gc_bucket_uri',
'            ))',
'            where object_name like ''%.zip''',
'        )',
'        loop',
'            -- Parse the timestamp from the filename: -YYYYMMDD_HH24MISS.zip',
'            l_ts_text := regexp_substr(r.object_name, ''-(\d{8}_\d{6})\.zip'', 1, 1, ''i'', 1);',
'',
'            -- Safety: only delete objects that match the expected naming pattern.',
'            if l_ts_text is not null then',
'                l_file_ts := to_timestamp(l_ts_text, ''YYYYMMDD_HH24MISS'');',
'',
'                if l_file_ts < l_cutoff then',
'                    dbms_cloud.delete_object(',
'                        credential_name => gc_credential,',
'                        object_uri      => gc_bucket_uri || r.object_name',
'                    );',
'                end if;',
'            end if;',
'        end loop;',
'    end purge_bicc_objectstore;',
'',
'',
'    -- =========================================================================',
'    -- DAILY BICC LOAD ORCHESTRATION',
'    -- =========================================================================',
'    -- Automatically loads and merges the latest BICC files from "today" (Pacific time)',
'    -- Called by DBMS_SCHEDULER job',
'    -- =========================================================================',
'',
'    procedure run_bicc_daily_today is',
'        c_pt_tz constant varchar2(64) := ''America/Los_Angeles'';',
'',
'        l_pt_today_date   date;',
'        l_utc_start_tstz  timestamp with time zone;',
'        l_utc_end_tstz    timestamp with time zone;',
'        l_utc_start_ts    timestamp;',
'        l_utc_end_ts      timestamp;',
'        l_job_id          number;',
'',
'    begin',
'        -- Compute the UTC window that corresponds to "today" in Pacific',
'        l_pt_today_date  := trunc(cast(systimestamp at time zone c_pt_tz as date));',
'',
'        l_utc_start_tstz := from_tz(cast(l_pt_today_date as timestamp), c_pt_tz) at time zone ''UTC'';',
'        l_utc_end_tstz   := l_utc_start_tstz + interval ''1'' day;',
'',
'        l_utc_start_ts   := cast(l_utc_start_tstz as timestamp); -- UTC timestamp (no tz)',
'        l_utc_end_ts     := cast(l_utc_end_tstz   as timestamp);',
'',
'        -- 1) Refresh the file list',
'        refresh_bicc_files;',
'',
'        -- 2) For each load_type, pick the latest file from "today PT", but only if not already processed',
'        for r in (',
'            with candidates as (',
'                select',
'                    f.file_name,',
'                    f.load_type,',
'                    f.file_timestamp,',
'                    row_number() over (',
'                        partition by f.load_type',
'                        order by f.file_timestamp desc nulls last, f.file_name desc',
'                    ) rn',
'                from bicc_files f',
'                where f.loader_available = ''Y''',
'                    and f.load_type in (''AP_INVOICE_HDR'',''PO_HDR'',''PO_LINES'',''SUPPLIER_HDR'',''HCM_EMPLOYEE'')',
'',
'                    -- filter to files whose FILE_TIMESTAMP falls within today''s Pacific day (expressed in UTC)',
'                    and f.file_timestamp >= l_utc_start_ts',
'                    and f.file_timestamp <  l_utc_end_ts',
'',
'                    --  exclusions',
'                    and lower(f.file_name) not like ''%poheaderdffpublic%''',
'                    and lower(f.file_name) not like ''%suppliersiteextract%''',
'                    and lower(f.file_name) not like ''%invoiceheaderextract%''',
'            )',
'            select c.file_name, c.load_type, c.file_timestamp',
'            from candidates c',
'            where c.rn = 1',
'',
'                -- skip if already merged for this exact file+type',
'                and not exists (',
'                    select 1',
'                    from bicc_load_job j',
'                    where j.file_name = c.file_name',
'                        and j.load_type = c.load_type',
'                        and j.status    = ''MERGED''',
'                )',
'',
'                -- skip if already staged/loading/loaded for this exact file+type (avoid duplicate job rows)',
'                and not exists (',
'                    select 1',
'                    from bicc_load_job j',
'                    where j.file_name = c.file_name',
'                        and j.load_type = c.load_type',
'                        and j.status in (''LOADING'',''STAGED'',''LOADED'')',
'                )',
'',
'            order by c.file_timestamp',
'        )',
'        loop',
'            l_job_id := null;',
'',
'            -- Stage (your functions insert into BICC_LOAD_JOB)',
'            case r.load_type',
'                when ''AP_INVOICE_HDR'' then l_job_id := pkg_bicc_ap_invoice_hdr.load_and_preview(r.file_name);',
'                when ''PO_HDR''         then l_job_id := pkg_bicc_po_hdr.load_and_preview(r.file_name);',
'                when ''PO_LINES''       then l_job_id := pkg_bicc_po_lines.load_and_preview(r.file_name);',
'                when ''SUPPLIER_HDR''   then l_job_id := pkg_bicc_supplier_hdr.load_and_preview(r.file_name);',
'                when ''HCM_EMPLOYEE''   then l_job_id := pkg_bicc_hcm_employee.load_and_preview(r.file_name);',
'                else',
'                    raise_application_error(-20001, ''Unsupported load_type: '' || r.load_type);',
'            end case;',
'',
'            -- Merge',
'            case r.load_type',
'                when ''AP_INVOICE_HDR'' then pkg_bicc_ap_invoice_hdr.merge(p_job_id => l_job_id);',
'                when ''PO_HDR''         then pkg_bicc_po_hdr.merge(p_job_id => l_job_id);',
'                when ''PO_LINES''       then pkg_bicc_po_lines.merge(p_job_id => l_job_id);',
'                when ''SUPPLIER_HDR''   then pkg_bicc_supplier_hdr.merge(p_job_id => l_job_id);',
'                when ''HCM_EMPLOYEE''   then pkg_bicc_hcm_employee.merge(p_job_id => l_job_id);',
'            end case;',
'',
'            commit;',
'        end loop;',
'',
'    exception',
'        when others then',
'            rollback;',
'            raise;',
'    end run_bicc_daily_today;',
'',
'end pkg_bicc_common;',
'/',
'create or replace package body pkg_bicc_hcm_employee as',
'',
'    -- =========================================================================',
'    -- LOAD (private)',
'    -- =========================================================================',
unistr('    -- Flow: extract_and_stage_csv \2192 COPY_DATA \2192 INSERT...SELECT'),
'    -- =========================================================================',
'',
'    procedure load(',
'        p_file_name  in varchar2,',
'        p_job_id     in number',
'    ) is',
'        l_error_msg     varchar2(4000);',
'        l_rows_inserted number := 0;',
'        l_run_id        varchar2(64) := sys_guid();',
'        l_staging_uri   varchar2(500);',
'    begin',
'        delete from stg_fbx_hcm_employee where job_id = p_job_id;',
'',
'        -- Step 1: Extract CSV from ZIP, upload to Object Storage',
'        pkg_bicc_common.extract_and_stage_csv(',
'            p_file_name    => p_file_name,',
'            p_staging_name => ''staging/hcm_employee_current.csv''',
'        );',
'',
'        -- Step 2: Load CSV into landing table via COPY_DATA',
'        execute immediate ''TRUNCATE TABLE landing_hcm_employee'';',
'',
'        l_staging_uri := pkg_bicc_common.gc_bucket_uri || ''staging/hcm_employee_current.csv'';',
'',
'        dbms_cloud.copy_data(',
'            table_name      => ''LANDING_HCM_EMPLOYEE'',',
'            credential_name => pkg_bicc_common.gc_credential,',
'            file_uri_list   => l_staging_uri,',
'            format          => json_object(',
'                                 ''type'' value ''csv'',',
'                                 ''skipheaders'' value ''1''',
'                               )',
'        );',
'',
'        -- Step 3: Cherry-pick columns from landing into staging',
'        insert into stg_fbx_hcm_employee (',
'            job_id,',
'            person_id,',
'            person_number,',
'            display_name,',
'            first_name,',
'            last_name,',
'            known_as,',
'            legislation_code,',
'            user_name,',
'            user_suspended_flag,',
'            work_email,',
'            person_type,',
'            hire_date_raw,',
'            hire_date_ts,',
'            termination_date_raw,',
'            termination_date_ts,',
'            assignment_id,',
'            assignment_number,',
'            assignment_name,',
'            assignment_status_type,',
'            assignment_type,',
'            employment_category,',
'            full_part_time,',
'            hourly_salaried_code,',
'            normal_hours,',
'            asg_effective_start_raw,',
'            asg_effective_start_ts,',
'            asg_effective_end_raw,',
'            asg_effective_end_ts,',
'            effective_latest_change_flag,',
'            primary_assignment_flag,',
'            primary_work_rel_flag,',
'            position_code,',
'            position_name,',
'            org_id,',
'            org_name,',
'            location_name,',
'            addr_city,',
'            addr_state,',
'            addr_postal_code,',
'            addr_country,',
'            manager_person_id,',
'            manager_display_name,',
'            manager_email,',
'            manager_user_name,',
'            manager_type,',
'            last_extract_run_id,',
'            last_extract_run_ts',
'        )',
'        select',
'            p_job_id,',
'',
'            -- Person / Name',
'            pkg_bicc_common.safe_to_number(l.PERSONID),',
'            coalesce(l.PERSONDETAILSPEOPERSONNUMBER, l.PERSONDETAILSPEO1PERSONNUMBER),',
'            coalesce(l.PERSONNAMEPEODISPLAYNAME, l.PERSONNAMEPEOFULLNAME),',
'            l.PERSONNAMEPEOFIRSTNAME,',
'            l.PERSONNAMEPEOLASTNAME,',
'            l.PERSONNAMEPEOKNOWNAS,',
'            l.PERSONNAMEPEOLEGISLATIONCODE,',
'',
'            -- User / Email',
'            l.USERPEOUSERNAME,',
'            l.USERPEOSUSPENDED,',
'            coalesce(l.WORKEMAILADDRESSESPEOEMAILADDRESS, l.EMAILADDRESSESPEOEMAILADDRESS),',
'',
'            -- Person Type',
'            l.PERSONTYPESTRANSLATIONPEOUSERPERSONTYPE,',
'',
'            -- Hire / Termination (keep raw + convert)',
'            l.PERIODOFSERVICEPEODATESTART,',
'            pkg_bicc_common.safe_to_timestamp(l.PERIODOFSERVICEPEODATESTART),',
'            l.PERIODOFSERVICEPEOACTUALTERMINATIONDATE,',
'            pkg_bicc_common.safe_to_timestamp(l.PERIODOFSERVICEPEOACTUALTERMINATIONDATE),',
'',
'            -- Assignment',
'            pkg_bicc_common.safe_to_number(l.ASSIGNMENTPEOASSIGNMENTID),',
'            l.ASSIGNMENTPEOASSIGNMENTNUMBER,',
'            l.ASSIGNMENTPEOASSIGNMENTNAME,',
'            l.ASSIGNMENTPEOASSIGNMENTSTATUSTYPE,',
'            l.ASSIGNMENTPEOASSIGNMENTTYPE,',
'            l.ASSIGNMENTPEOEMPLOYMENTCATEGORY,',
'            l.ASSIGNMENTPEOFULLPARTTIME,',
'            l.ASSIGNMENTPEOHOURLYSALARIEDCODE,',
'            pkg_bicc_common.safe_to_number(l.ASSIGNMENTPEONORMALHOURS),',
'',
'            l.ASSIGNMENTPEOEFFECTIVESTARTDATE,',
'            pkg_bicc_common.safe_to_timestamp(l.ASSIGNMENTPEOEFFECTIVESTARTDATE),',
'            l.ASSIGNMENTPEOEFFECTIVEENDDATE,',
'            pkg_bicc_common.safe_to_timestamp(l.ASSIGNMENTPEOEFFECTIVEENDDATE),',
'',
'            l.ASSIGNMENTPEOEFFECTIVELATESTCHANGE,',
'            l.ASSIGNMENTPEOPRIMARYASSIGNMENTFLAG,',
'            l.ASSIGNMENTPEOPRIMARYWORKRELATIONFLAG,',
'',
'            -- Position / Org / Location',
'            l.POSITIONMGRPEOPOSITIONCODE,',
'            l.POSITIONTRANSLATIONMGRPEONAME,',
'            pkg_bicc_common.safe_to_number(l.ORGANIZATIONUNITPEOORGANIZATIONID),',
'            l.ORGUNITTRANSLATIONMGRPEONAME,',
'            l.LOCATIONDETAILSMGRPEOLOCATIONNAME,',
'',
'            -- Address',
'            l.ADDRESSESPEOTOWNORCITY,',
'            l.ADDRESSESPEOREGION2,',
'            l.ADDRESSESPEOPOSTALCODE,',
'            l.ADDRESSESPEOCOUNTRY,',
'',
'            -- Manager',
'            pkg_bicc_common.safe_to_number(l.ASSIGNMENTSUPERVISORPEOMANAGERID),',
'            l.SUPERVISORNAMEPEODISPLAYNAME,',
'            l.SUPERVISOREMAILADDRESSPEOEMAILADDRESS,',
'            l.SUPERVISORUSERPEOUSERNAME,',
'            l.ASSIGNMENTSUPERVISORPEOMANAGERTYPE,',
'',
'            -- Run metadata',
'            l_run_id,',
'            systimestamp',
'',
'        from landing_hcm_employee l;',
'',
'        l_rows_inserted := sql%rowcount;',
'        commit;',
'',
'        insert into bicc_load_log (',
'            load_type, file_name, step, rows_processed, rows_inserted, status',
'        ) values (',
'            ''HCM_EMPLOYEE'', p_file_name, ''LOAD_STG'', l_rows_inserted, l_rows_inserted, ''SUCCESS''',
'        );',
'        commit;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            rollback;',
'            insert into bicc_load_log (',
'                load_type, file_name, step, status, error_message',
'            ) values (',
'                ''HCM_EMPLOYEE'', p_file_name, ''LOAD_STG'', ''ERROR'', l_error_msg',
'            );',
'            commit;',
'            raise;',
'    end load;',
'',
'',
'    -- =========================================================================',
'    -- PREVIEW (private)',
'    -- =========================================================================',
'',
'    procedure preview(',
'        p_job_id          in  number,',
'        p_new_count       out number,',
'        p_changed_count   out number,',
'        p_unchanged_count out number',
'    ) is',
'        l_matched number;',
'    begin',
'        select count(*) into p_new_count',
'        from (',
'            select distinct person_id',
'            from stg_fbx_hcm_employee',
'            where job_id = p_job_id',
'              and nvl(primary_assignment_flag,''N'') = ''Y''',
'              and nvl(effective_latest_change_flag,''N'') = ''Y''',
'              and person_id is not null',
'        ) s',
'        where not exists (',
'            select 1 from fbx_hcm_employee f where f.person_id = s.person_id',
'        );',
'',
'        select count(*) into l_matched',
'        from (',
'            select distinct person_id',
'            from stg_fbx_hcm_employee',
'            where job_id = p_job_id',
'              and nvl(primary_assignment_flag,''N'') = ''Y''',
'              and nvl(effective_latest_change_flag,''N'') = ''Y''',
'              and person_id is not null',
'        ) s',
'        where exists (',
'            select 1 from fbx_hcm_employee f where f.person_id = s.person_id',
'        );',
'',
'        select count(*) into p_unchanged_count',
'        from (',
'            select',
'                person_id,',
'                person_number,',
'                display_name,',
'                work_email,',
'                user_name,',
'                user_suspended_flag,',
'                person_type,',
'                hire_date_ts,',
'                termination_date_ts,',
'                assignment_id,',
'                assignment_number,',
'                assignment_name,',
'                assignment_status_type,',
'                employment_category,',
'                full_part_time,',
'                hourly_salaried_code,',
'                normal_hours,',
'                position_code,',
'                position_name,',
'                org_name,',
'                location_name,',
'                manager_display_name,',
'                manager_email,',
'                manager_type',
'            from (',
'                select s.*,',
'                       row_number() over (',
'                         partition by person_id',
'                         order by asg_effective_start_ts desc nulls last, rowid',
'                       ) rn',
'                from stg_fbx_hcm_employee s',
'                where job_id = p_job_id',
'                  and nvl(primary_assignment_flag,''N'') = ''Y''',
'                  and nvl(effective_latest_change_flag,''N'') = ''Y''',
'                  and person_id is not null',
'            )',
'            where rn = 1',
'            intersect',
'            select',
'                person_id,',
'                person_number,',
'                display_name,',
'                work_email,',
'                user_name,',
'                user_suspended_flag,',
'                person_type,',
'                hire_date_ts,',
'                termination_date_ts,',
'                assignment_id,',
'                assignment_number,',
'                assignment_name,',
'                assignment_status_type,',
'                employment_category,',
'                full_part_time,',
'                hourly_salaried_code,',
'                normal_hours,',
'                position_code,',
'                position_name,',
'                org_name,',
'                location_name,',
'                manager_display_name,',
'                manager_email,',
'                manager_type',
'            from fbx_hcm_employee',
'        );',
'',
'        p_changed_count := l_matched - p_unchanged_count;',
'    end preview;',
'',
'',
'    -- =========================================================================',
'    -- LOAD AND PREVIEW (public)',
'    -- =========================================================================',
'',
'    function load_and_preview(p_file_name in varchar2) return number is',
'        l_job_id      number;',
'        l_rows_loaded number;',
'        l_new         number;',
'        l_changed     number;',
'        l_unchanged   number;',
'        l_error_msg   varchar2(4000);',
'    begin',
'        insert into bicc_load_job (',
'            load_type, file_name, status, loaded_by, loaded_ts',
'        ) values (',
'            ''HCM_EMPLOYEE'', p_file_name, ''LOADING'', coalesce(v(''APP_USER''), user), systimestamp',
'        )',
'        returning job_id into l_job_id;',
'',
'        load(p_file_name => p_file_name, p_job_id => l_job_id);',
'',
'        select count(distinct person_id) into l_rows_loaded',
'        from stg_fbx_hcm_employee',
'        where job_id = l_job_id',
'          and person_id is not null;',
'',
'        preview(',
'            p_job_id          => l_job_id,',
'            p_new_count       => l_new,',
'            p_changed_count   => l_changed,',
'            p_unchanged_count => l_unchanged',
'        );',
'',
'        update bicc_load_job',
'        set rows_loaded     = l_rows_loaded,',
'            new_count       = l_new,',
'            changed_count   = l_changed,',
'            unchanged_count = l_unchanged,',
'            status          = ''STAGED''',
'        where job_id = l_job_id;',
'',
'        commit;',
'        return l_job_id;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            update bicc_load_job',
'            set status        = ''ERROR'',',
'                error_message = l_error_msg',
'            where job_id = l_job_id;',
'            commit;',
'            raise;',
'    end load_and_preview;',
'',
'',
'    -- =========================================================================',
'    -- MERGE (public)',
'    -- =========================================================================',
'',
'    procedure merge(p_job_id in number) is',
'        l_rowcount  number := 0;',
'        l_error_msg varchar2(4000);',
'    begin',
'        merge into fbx_hcm_employee f',
'        using (',
'            select * from (',
'                select',
'                    s.*,',
'                    row_number() over (',
'                        partition by person_id',
'                        order by asg_effective_start_ts desc nulls last, rowid',
'                    ) rn',
'                from stg_fbx_hcm_employee s',
'                where job_id = p_job_id',
'                  and nvl(primary_assignment_flag,''N'') = ''Y''',
'                  and nvl(effective_latest_change_flag,''N'') = ''Y''',
'                  and person_id is not null',
'            )',
'            where rn = 1',
'        ) s',
'        on (f.person_id = s.person_id)',
'        when matched then update set',
'            f.person_number            = s.person_number,',
'            f.display_name             = s.display_name,',
'            f.first_name               = s.first_name,',
'            f.last_name                = s.last_name,',
'            f.known_as                 = s.known_as,',
'            f.legislation_code         = s.legislation_code,',
'            f.user_name                = s.user_name,',
'            f.user_suspended_flag      = s.user_suspended_flag,',
'            f.work_email               = s.work_email,',
'            f.person_type              = s.person_type,',
'            f.hire_date_ts             = s.hire_date_ts,',
'            f.termination_date_ts      = s.termination_date_ts,',
'            f.assignment_id            = s.assignment_id,',
'            f.assignment_number        = s.assignment_number,',
'            f.assignment_name          = s.assignment_name,',
'            f.assignment_status_type   = s.assignment_status_type,',
'            f.assignment_type          = s.assignment_type,',
'            f.employment_category      = s.employment_category,',
'            f.full_part_time           = s.full_part_time,',
'            f.hourly_salaried_code     = s.hourly_salaried_code,',
'            f.normal_hours             = s.normal_hours,',
'            f.asg_effective_start_ts   = s.asg_effective_start_ts,',
'            f.asg_effective_end_ts     = s.asg_effective_end_ts,',
'            f.position_code            = s.position_code,',
'            f.position_name            = s.position_name,',
'            f.org_id                   = s.org_id,',
'            f.org_name                 = s.org_name,',
'            f.location_name            = s.location_name,',
'            f.addr_city                = s.addr_city,',
'            f.addr_state               = s.addr_state,',
'            f.addr_postal_code         = s.addr_postal_code,',
'            f.addr_country             = s.addr_country,',
'            f.manager_person_id        = s.manager_person_id,',
'            f.manager_display_name     = s.manager_display_name,',
'            f.manager_email            = s.manager_email,',
'            f.manager_user_name        = s.manager_user_name,',
'            f.manager_type             = s.manager_type,',
'            f.last_extract_run_id      = s.last_extract_run_id,',
'            f.last_extract_run_ts      = s.last_extract_run_ts',
'        when not matched then insert (',
'            person_id,',
'            person_number,',
'            display_name,',
'            first_name,',
'            last_name,',
'            known_as,',
'            legislation_code,',
'            user_name,',
'            user_suspended_flag,',
'            work_email,',
'            person_type,',
'            hire_date_ts,',
'            termination_date_ts,',
'            assignment_id,',
'            assignment_number,',
'            assignment_name,',
'            assignment_status_type,',
'            assignment_type,',
'            employment_category,',
'            full_part_time,',
'            hourly_salaried_code,',
'            normal_hours,',
'            asg_effective_start_ts,',
'            asg_effective_end_ts,',
'            position_code,',
'            position_name,',
'            org_id,',
'            org_name,',
'            location_name,',
'            addr_city,',
'            addr_state,',
'            addr_postal_code,',
'            addr_country,',
'            manager_person_id,',
'            manager_display_name,',
'            manager_email,',
'            manager_user_name,',
'            manager_type,',
'            last_extract_run_id,',
'            last_extract_run_ts',
'        ) values (',
'            s.person_id,',
'            s.person_number,',
'            s.display_name,',
'            s.first_name,',
'            s.last_name,',
'            s.known_as,',
'            s.legislation_code,',
'            s.user_name,',
'            s.user_suspended_flag,',
'            s.work_email,',
'            s.person_type,',
'            s.hire_date_ts,',
'            s.termination_date_ts,',
'            s.assignment_id,',
'            s.assignment_number,',
'            s.assignment_name,',
'            s.assignment_status_type,',
'            s.assignment_type,',
'            s.employment_category,',
'            s.full_part_time,',
'            s.hourly_salaried_code,',
'            s.normal_hours,',
'            s.asg_effective_start_ts,',
'            s.asg_effective_end_ts,',
'            s.position_code,',
'            s.position_name,',
'            s.org_id,',
'            s.org_name,',
'            s.location_name,',
'            s.addr_city,',
'            s.addr_state,',
'            s.addr_postal_code,',
'            s.addr_country,',
'            s.manager_person_id,',
'            s.manager_display_name,',
'            s.manager_email,',
'            s.manager_user_name,',
'            s.manager_type,',
'            s.last_extract_run_id,',
'            s.last_extract_run_ts',
'        );',
'',
'        l_rowcount := sql%rowcount;',
'',
'        delete from stg_fbx_hcm_employee where job_id = p_job_id;',
'',
'        update bicc_load_job',
'        set status    = ''MERGED'',',
'            merged_by = coalesce(v(''APP_USER''), user),',
'            merged_ts = systimestamp',
'        where job_id = p_job_id;',
'',
'        insert into bicc_load_log (',
'            load_type, step, rows_updated, status',
'        ) values (',
'            ''HCM_EMPLOYEE'', ''MERGE_FBX'', l_rowcount, ''SUCCESS''',
'        );',
'',
'        commit;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            rollback;',
'            insert into bicc_load_log (',
'                load_type, step, status, error_message',
'            ) values (',
'                ''HCM_EMPLOYEE'', ''MERGE_FBX'', ''ERROR'', l_error_msg',
'            );',
'            commit;',
'            raise;',
'    end merge;',
'',
'end pkg_bicc_hcm_employee;',
'/',
'create or replace package body pkg_bicc_po_hdr as',
'',
'    -- =========================================================================',
'    -- LOAD (private)',
'    -- =========================================================================',
unistr('    -- Flow: extract_and_stage_csv \2192 COPY_DATA \2192 INSERT...SELECT'),
'    -- =========================================================================',
'',
'    procedure load(',
'        p_file_name  in varchar2,',
'        p_job_id     in number',
'    ) is',
'        l_error_msg     varchar2(4000);',
'        l_rows_inserted number := 0;',
'        l_run_id        varchar2(64) := sys_guid();',
'        l_staging_uri   varchar2(500);',
'    begin',
'        delete from stg_fbx_po_hdr where job_id = p_job_id;',
'',
'        -- Step 1: Extract CSV from ZIP, upload to Object Storage',
'        pkg_bicc_common.extract_and_stage_csv(',
'            p_file_name    => p_file_name,',
'            p_staging_name => ''staging/po_hdr_current.csv''',
'        );',
'',
'        -- Step 2: Load CSV into landing table via COPY_DATA',
'        execute immediate ''TRUNCATE TABLE landing_po_hdr'';',
'',
'        l_staging_uri := pkg_bicc_common.gc_bucket_uri || ''staging/po_hdr_current.csv'';',
'',
'        dbms_cloud.copy_data(',
'            table_name      => ''LANDING_PO_HDR'',',
'            credential_name => pkg_bicc_common.gc_credential,',
'            file_uri_list   => l_staging_uri,',
'            format          => json_object(',
'                                 ''type'' value ''csv'',',
'                                 ''skipheaders'' value ''1''',
'                               )',
'        );',
'',
'        -- Step 3: Cherry-pick columns from landing into staging',
'        insert into stg_fbx_po_hdr (',
'            job_id,',
'            poheaderid,',
'            po_number,',
'            revisionnum,',
'            po_type,',
'            documentstatus,',
'            approvedflag,',
'            prcbuid,',
'            vendorid,',
'            vendorsiteid,',
'            vendor_order_num,',
'            currencycode,',
'            amountlimit,',
'            amountreleased,',
'            blankettotalamount,',
'            startdate_raw,',
'            creationdate_raw,',
'            lastupdatedate_raw,',
'            closeddate_raw,',
'    '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(219910759296195542)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'        startdate_ts,',
'            creationdate_ts,',
'            lastupdatedate_ts,',
'            closeddate_ts,',
'            lastupdatedby,',
'            objectversionnumber,',
'            last_extract_run_id,',
'            last_extract_run_ts',
'        )',
'        select',
'            p_job_id,',
'            pkg_bicc_common.safe_to_number(l.POHEADERID),',
'            l.SEGMENT1,',
'            pkg_bicc_common.safe_to_number(l.REVISIONNUM),',
'            l.TYPELOOKUPCODE,',
'            l.DOCUMENTSTATUS,',
'            l.APPROVEDFLAG,',
'            pkg_bicc_common.safe_to_number(l.PRCBUID),',
'            pkg_bicc_common.safe_to_number(l.VENDORID),',
'            pkg_bicc_common.safe_to_number(l.VENDORSITEID),',
'            l.VENDORORDERNUM,',
'            l.CURRENCYCODE,',
'            pkg_bicc_common.safe_to_number(l.AMOUNTLIMIT),',
'            pkg_bicc_common.safe_to_number(l.MINRELEASEAMOUNT),',
'            pkg_bicc_common.safe_to_number(l.BLANKETTOTALAMOUNT),',
'            l.STARTDATE,',
'            l.CREATIONDATE,',
'            l.LASTUPDATEDATE,',
'            l.CLOSEDDATE,',
'            pkg_bicc_common.safe_to_timestamp(l.STARTDATE),',
'            pkg_bicc_common.safe_to_timestamp(l.CREATIONDATE),',
'            pkg_bicc_common.safe_to_timestamp(l.LASTUPDATEDATE),',
'            pkg_bicc_common.safe_to_timestamp(l.CLOSEDDATE),',
'            l.LASTUPDATEDBY,',
'            pkg_bicc_common.safe_to_number(l.OBJECTVERSIONNUMBER),',
'            l_run_id,',
'            systimestamp',
'        from landing_po_hdr l;',
'',
'        l_rows_inserted := sql%rowcount;',
'        commit;',
'',
'        insert into bicc_load_log (',
'            load_type, file_name, step, rows_processed, rows_inserted, status',
'        ) values (',
'            ''PO_HDR'', p_file_name, ''LOAD_STG'', l_rows_inserted, l_rows_inserted, ''SUCCESS''',
'        );',
'        commit;',
'',
'    exception',
'        when others then',
'            l_error_msg := sqlerrm;',
'            rollback;',
'            insert into bicc_load_log (',
'                load_type, file_name, step, status, error_message',
'            ) values (',
'                ''PO_HDR'', p_file_name, ''LOAD_STG'', ''ERROR'', l_error_msg',
'            );',
'            commit;',
'            raise;',
'    end load;',
'',
'',
'    -- =========================================================================',
'    -- PREVIEW (private)',
'    -- =========================================================================',
'',
'    procedure preview(',
'        p_job_id          in  number,',
'        p_new_count       out number,',
'        p_changed_count   out number,',
'        p_unchanged_count out number',
'    ) is',
'        l_matched number;',
'    begin',
'        select count(*) into p_new_count',
'        from (',
'            select distinct poheaderid',
'            from stg_fbx_po_hdr',
'            where job_id = p_job_id',
'        ) s',
'        where not exists (',
'            select 1 from fbx_po_hdr f where f.poheaderid = s.poheaderid',
'        );',
'',
'        select count(*) into l_matched',
'        from (',
'            select distinct poheaderid',
'            from stg_fbx_po_hdr',
'            where job_id = p_job_id',
'        ) s',
'        where exists (',
'            select 1 from fbx_po_hdr f where f.poheaderid = s.poheaderid',
'        );',
'',
'        select count(*) into p_unchanged_count',
'        from (',
'            select',
'                poheaderid,',
'                po_number,',
'                revisionnum,',
'                po_type,',
'                documentstatus,',
'                approvedflag,',
'                prcbuid,',
'                vendorid,',
'                vendorsiteid,',
'                vendor_order_num,',
'                currencycode,',
'                amountlimit,',
'                amountreleased,',
'                blankettotalamount',
'            from (',
'                select',
'                    s.*,',
'                    row_number() over (partition by poheaderid order by rowid) rn',
'                from stg_fbx_po_hdr s',
'                where job_id = p_job_id',
'            )',
'            where rn = 1',
'            intersect',
'            select',
'                poheaderid,',
'                po_number,',
'                revisionnum,',
'                po_type,',
'                documentstatus,',
'                approvedflag,',
'                prcbuid,',
'                vendorid,',
'                vendorsiteid,',
'                vendor_order_num,',
'                currencycode,',
'                amountlimit,',
'                amountreleased,',
'                blankettotalamount',
'            from fbx_po_hdr',
'        );',
'',
'        p_changed_count := l_matched - p_unchanged_count;',
'    end preview;',
'',
'',
'    -- =========================================================================',
'    -- LOAD AND PREVIEW (public)',
'    -- =========================================================================',
'',
'    function load_and_preview(p_file_name in varchar2) return number is',
'        l_job_id      number;',
'        l_rows_loaded number;',
'        l_new         number;',
'        l_changed     number;',
'        l_unchanged   number;',
'        l_error_msg   varchar2(4000);',
'    begin',
'        insert into bicc_load_job (',
'            load_type, file_name, status, loaded_by, loaded_ts',
'        ) values (',
